'select wwv_flow_lang.system_message(''CONFIRM.RPT_TEMPLATE_NAME2'')  d,  2 r from sys.dual union',
'select wwv_flow_lang.system_message(''CONFIRM.RPT_TEMPLATE_NAME21'') d, 21 r from sys.dual union',
'select wwv_flow_lang.system_message(''CONFIRM.RPT_TEMPLATE_NAME22'') d, 22 r from sys.dual union',
'select wwv_flow_lang.system_message(''CONFIRM.TEMPLATE'')||'' ''||theme_id||''. ''||wwv_flow_escape.html(row_template_name) d, id r',
'  from wwv_theme_report_templates ',
' where current_app_theme_id = :FB_THEME_ID',
' order by 1'))
,p_source_type=>'LEGACY_SQL'
,p_location=>'LOCAL'
,p_version_scn=>72475287
);
