prompt --application/shared_components/user_interface/lovs/report_layouts
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(24313105570265439.4008)
,p_lov_name=>'REPORT_LAYOUTS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id, report_layout_name ',
'  from wwv_flow_report_layouts ',
' where flow_id              = :FB_FLOW_ID ',
'   and security_group_id    = :WORKSPACE_ID',
'   and (    ( :F4000_PRINT_SERVER_TYPE = ''DOCUMENT_GENERATOR'' and report_layout_type in ( ''DOCX_FILE'', ''XLSX_FILE'' ) )',
'        or  ( :F4000_PRINT_SERVER_TYPE = ''ADVANCED'' and report_layout_type in (''XSL_GENERIC'', ''RTF_FILE'', ''XSL_FILE'' ) )',
'        or  ( :F4000_PRINT_SERVER_TYPE = ''STANDARD'' and report_layout_type in (''XSL_GENERIC'', ''XSL_FILE'' ) )',
'        or  ( :F4000_PRINT_SERVER_TYPE = ''AOP'' and report_layout_type in (''DOCX_FILE'',',
'                                                                          ''XLSX_FILE'',',
'                                                                          ''PPTX_FILE'',',
'                                                                          ''HTML_FILE'',',
'                                                                          ''MARKDOWN_FILE'',',
'                                                                          ''CSV_FILE'',',
'                                                                          ''TXT_FILE'',',
'                                                                          ''ODT_FILE'',',
'                                                                          ''ODS_FILE'',',
'                                                                          ''ODP_FILE'' ) ) )'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'ID'
,p_display_column_name=>'REPORT_LAYOUT_NAME'
