wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1020628401159693462.4008)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'security'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'wwv_flow_error.raise_internal_error(',
'    p_error_message => wwv_flow_lang.system_message( p_name => ''F4000.P1.APP_DOES_NOT_EXIST'',',
'                                                     p0     => wwv_flow_escape.html( nvl( :FB_FLOW_ID, ''NULL'' ) ) ) );'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null',
'  from wwv_flows',
' where security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and id = :FB_FLOW_ID',
'   and build_status = ''RUN_AND_BUILD'''))
,p_process_when_type=>'NOT_EXISTS'
,p_internal_uid=>1020628401159693462.4008
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(231747163006396029.4008)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Compute Badge Counts'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    -- Application Items',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_items i',
'      where i.flow_id = :FB_FLOW_ID',
'        and i.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_items,',
'',
'    -- Application Processes',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_processing p',
'      where p.flow_id = :FB_FLOW_ID',
'        and p.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_processes,',
'',
'    -- Application Computations',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_computations c',
'      where c.flow_id = :FB_FLOW_ID',
'        and c.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_computations,',
'',
'     -- Application Settings',
'     to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_app_settings s',
'      where flow_id = :FB_FLOW_ID',
'        and security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_settings,',
'',
'     -- Automations',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_automations a',
'      where a.flow_id = :FB_FLOW_ID ',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_automations,',
'',
'     -- Build Options',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_patches b',
'      where b.flow_id = :FB_FLOW_ID ',
'        and b.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_build_options,',
'',
'     -- Authentication Schemes',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_authentications a',
'      where a.flow_id = :FB_FLOW_ID',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_authn_schemes,',
'',
'     -- Authorization Schemes',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_security_schemes a',
'      where a.flow_id = :FB_FLOW_ID',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_authz_schemes,',
'',
'     -- Appplication Access Control Roles',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_fnd_user_groups r',
'      where r.flow_id = :FB_FLOW_ID',
'        and r.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_app_access_roles,',
'     ',
'     -- Lists of Values',
'    to_char(nullif( ',
'    (select count(*) ',
'       from wwv_flow_lists_of_values$ l',
'      where flow_id = :FB_FLOW_ID ',
'        and security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_lovs,',
'',
'     -- Plug-ins',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_plugins p',
'      where p.flow_id = :FB_FLOW_ID',
'        and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
'        and p.theme_id is null), 0), ''fm999G999G999G999'') as p9_plugins,',
'     ',
'     -- Shortcuts',
