wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(479780812892535082.4008)
,p_process_sequence=>20
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'    :P67_IMP_COMPANY := wwv_flow_imp_parser.get_security_group_id (p_file_id => :P49_FILE_ID);',
'    :P67_IMP_PAGE_ID := wwv_flow_imp_parser.get_page_id (p_file_id => :P49_FILE_ID);',
'    :P67_IMP_VERSION := wwv_flow_imp_parser.get_version (:P49_FILE_ID);',
'',
'    begin',
'      select build_status ',
'        into :P67_INSTALL from wwv_flows ',
'       where id = :FB_FLOW_ID',
'         and security_group_id = :WORKSPACE_ID;',
'    exception when no_data_found then',
'        :P67_INSTALL := ''N'';',
'    end;',
'',
'    if :P67_INSTALL = ''RUN_ONLY'' then',
'        -- cannot install page is app is not editable',
'        :P67_INSTALL := ''RUN_ONLY'';',
'    else ',
'        if     :WORKSPACE_ID    = :P67_IMP_COMPANY',
'           and :P67_IMP_FLOW_ID = :FB_FLOW_ID then',
'            :P67_INSTALL := ''Y'';',
'            :P67_company_action := wwv_flow_lang.system_message(''F4000.P67.EXPORTED_FROM_CURRENT_WORKSPACE'');',
'        else',
'            :P67_INSTALL := ''Y'';',
'            :P67_company_action := wwv_flow_lang.system_message(''F4000.P67.EXPORTED_FROM_ANOTHER_APP_OR_WORKSPACE'');',
'        end if;',
'    end if;',
'',
'    for c1 in (',
'        select locked_by',
'          from wwv_flow_steps p,',
'               WWV_FLOW_LOCK_PAGE l',
'         where p.flow_id = :P67_IMP_FLOW_ID',
'           and p.id      = :P67_IMP_PAGE_ID',
'           and p.flow_id = l.flow_id(+)',
'           and p.id      = l.object_id(+)',
'           and p.security_group_id = :flow_security_group_id )',
'        loop',
'           if c1.locked_by is not null then',
'              :P67_INSTALL := ''N'';',
'              :P67_company_action := ',
'                   wwv_flow_lang.system_message(''F4000.P67.PAGE_LOCKED'');',
'           end if;',
'    end loop;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>479780812892535082.4008
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(77712212771857073.4008)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'install page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_flow_id           number  := wwv_flow_imp_parser.get_flow_id(p_file_id => :P67_FILE_ID);',
'begin',
'    wwv_flow_imp_parser.parse(',
'        p_file_id          => :P67_FILE_ID,',
'        p_parse_as_schema  => :P67_PARSE_AS,',
'        p_install_as_flow  => :P67_NEW_FLOW_ID,',
'        p_original_flow_id => l_flow_id,',
'        p_adjust_offset    => false',
'    );',
' ',
'    -- get imported page id to redirect to the new page',
'    :FB_FLOW_ID := :P67_NEW_FLOW_ID;',
'    :FB_FLOW_PAGE_ID := :P67_IMP_PAGE_ID;   ',
'    :F4000_P1_PAGE := :P67_IMP_PAGE_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('\D398\C774\C9C0\B97C \C124\CE58\D558\B294 \C911 \C624\B958\AC00 \BC1C\C0DD\D588\C2B5\B2C8\B2E4.')
,p_process_when=>'INSTALL:REPLACE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>unistr('\D398\C774\C9C0\AC00 \C124\CE58\B418\C5C8\C2B5\B2C8\B2E4.')
,p_internal_uid=>77712212771857073.4008
);
end;
