,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Template Options'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'update wwv_flow_template_options t',
'   set t.template_types = ( select g.template_types ',
'                              from wwv_flow_template_opt_groups g',
'                             where g.id                = t.group_id',
'                               and g.flow_id           = t.flow_id',
'                               and g.security_group_id = t.security_group_id )',
' where t.flow_id           = :FB_FLOW_ID',
'   and t.security_group_id = :WORKSPACE_ID',
'   and exists ( select 1 ',
'                  from wwv_flow_template_opt_groups g',
'                 where g.id                = t.group_id',
'                   and g.flow_id           = t.flow_id',
'                   and g.security_group_id = t.security_group_id',
'                   and g.template_types    <> t.template_types );'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>7427995501981827.4008
);
