'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P26_COPY_FROM_FLOW_ID, :P225_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :F4000_P26_COPY_FROM_FLOW_ID, :P225_COPY_FROM_THEME )       as theme_id,',
