,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\D14C\B9C8 \C2A4\D0C0\C77C\C774 \CD5C\C2E0\C778 \ACBD\C6B0 \BAA8\B4E0 \D398\C774\C9C0\C5D0 \B85C\B4DC\D560 \C885\C18D\D615 \C2DC\D2B8 \D30C\C77C URL\C744 \C785\B825\D569\B2C8\B2E4. \AC01 URL\C740 \C0C8 \D589\C5D0 \C791\C131\D574\C57C \D569\B2C8\B2E4. \D30C\C77C\C758 \CD5C\C18C\D654\B41C \BC84\C804\C744 \C81C\ACF5\D560 \ACBD\C6B0, \C77C\BC18 \D398\C774\C9C0 \BCF4\AE30\B97C \C704\D574\C11C\B294 \D30C\C77C URL\C5D0 <code>.min</code>\C744 \D3EC\D568\D558\B3C4\B85D \B300\CCB4 \BB38\C790\C5F4 <code>#MIN#</code>\C744 \C0AC\C6A9\D558\AC70\B098 <code>minified/</code>\B97C \D3EC\D568\D558\B3C4\B85D <code>#MIN_DIRECTORY#</code>\B97C \C0AC\C6A9\D560 \C218 \C788\C73C\BA70, \D398\C774')
||unistr('\C9C0\B97C \B514\BC84\ADF8 \BAA8\B4DC\B85C \D45C\C2DC\D560 \B54C\B294 \BE48 \BB38\C790\C5F4\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \B610\D55C \C560\D50C\B9AC\CF00\C774\C158\C758 \BC84\C804\C744 \D30C\C77C URL\C5D0 \D3EC\D568\D558\B824\B294 \ACBD\C6B0 \B300\CCB4 \BB38\C790\C5F4 <code>#APP_VERSION#</code>\C5D0 \C561\C138\C2A4\D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p>\C5EC\AE30\C5D0 \C785\B825\D558\B294 \D30C\C77C URL\C740 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\C5D0\C11C <code>#THEME_STYLE_CSS#</code> \B300\CCB4 \BB38\C790\C5F4\C744 \BC14\AFC9\B2C8\B2E4.</p>'),
'',
unistr('<p>\CC38\ACE0: \C5F4\AE30 \B610\B294 \B2EB\AE30 <code>link</code> \D0DC\ADF8\B294 \D3EC\D568\D558\C9C0 \C54A\C544\B3C4 \B429\B2C8\B2E4. \D30C\C77C URL\B9CC \D3EC\D568\D558\C2ED\C2DC\C624.</p>'),
'',
'<p>',
unistr('\C608\C81C:'),
'<ul>',
unistr('  <li>\D14C\B9C8 \B514\B809\D1A0\B9AC\C5D0\C11C \D30C\C77C\C744 \B85C\B4DC\D558\B294 \D45C\C900 \D30C\C77C \CC38\C870\C785\B2C8\B2E4.'),
'      <pre>#THEME_IMAGES#main.css</pre>',
'  </li>',
unistr('  <li>\C77C\BC18 \D398\C774\C9C0 \BCF4\AE30\B97C \C704\D574 /mycss/minified/\C5D0\C11C \CD5C\C18C\D654\B41C \D30C\C77C main.min.css\B97C \B85C\B4DC\D558\ACE0 \B514\BC84\ADF8 \BAA8\B4DC\B85C /mycss/\C5D0\C11C main.css\B97C \B85C\B4DC\D558\B294 \D45C\C900 \D30C\C77C \CC38\C870\C785\B2C8\B2E4.'),
'      <pre>/mycss/#MIN_DIRECTORY#main#MIN#.css</pre>',
'  </li>',
unistr('  <li>\C870\AC74\BD80 \B9E4\CCB4 \C9C8\C758'),
'      <pre>[media="only screen and (max-device-width: 480px)"]/mycss/smartphone.css</pre>',
'  </li>',
unistr('  <li>\C560\D50C\B9AC\CF00\C774\C158\C744 \C5C5\ADF8\B808\C774\B4DC\D560 \B54C\C640 \AC19\C774(\BC84\C804\C774 \C99D\BD84\B428) \C560\D50C\B9AC\CF00\C774\C158 \BC84\C804\C744 \CC38\C870\D558\B294 URL\C758 \C9C8\C758 \BB38\C790\C5F4\C744 \C0AC\C6A9\D558\B294 \D30C\C77C \CC38\C870\C785\B2C8\B2E4. \BE0C\B77C\C6B0\C800\AC00 \D56D\C0C1 \C0C8 \D30C\C77C\C744 \B85C\B4DC\D558\ACE0 \C774\C804\C5D0 \CE90\C2DC\B41C \D30C\C77C\C740 \BB34\C2DC\D558\B3C4\B85D \C9C0\C815\B429\B2C8\B2E4.'),
'      <pre>/mycss/main.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
