wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(40585504519890825.4008)
,p_plug_name=>unistr('\D14C\B9C8')
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4008)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id,',
'       theme_id,',
'       current_theme_id,',
'       theme_name || (case when theme_id = current_theme_id then '' *'' end) as theme_name,',
'       version_identifier,',
'       icon_class,',
'       wwv_flow_utilities.prepare_url( edit_link ) edit_link,',
'       case when theme_id = current_theme_id then ''Y'' else ''N'' end as is_current,',
'       case when theme_id = current_theme_id then ''icon-check'' end as is_current_css,',
'       wwv_flow_theme_dev.is_universal_theme_yn(p_theme_id => id) as is_universal_theme,',
'       case when wwv_flow_theme_dev.is_universal_theme_yn(p_theme_id => id)=''Y'' then ''icon-check'' end as is_universal_theme_css,',
'       subscribed_from,',
'       subscribers,',
'       page_templates + region_templates + button_templates + menu_templates + list_templates + label_templates + report_templates + cal_templates + popup_templates + template_components all_templates,',
'       page_templates,',
'       region_templates,',
'       button_templates,',
'       menu_templates,',
'       list_templates,',
'       label_templates,',
'       report_templates,',
'       cal_templates,',
'       popup_templates,',
'       template_components',
'from (',
'select id,',
'      theme_id,',
'      (select theme_id as current_theme_id from wwv_flows where id=:fb_flow_id) as current_theme_id,',
'      theme_name || '' - '' || theme_id as theme_name,',
'      version_identifier,',
'      ''icon-sc-theme'' icon_class,',
'      wwv_flow_page_api.get_url (',
'          p_page => 267,',
'          p_items => ''P267_ID'',',
'          p_values => id,',
'          p_clear_cache => 267 ) edit_link,',
'       case when reference_id is not null then',
'           coalesce ( ( select case',
'                                 when security_group_id in ( 11, 12 ) then wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' )',
'                                 else to_char( flow_id )',
'                               end',
'                          from wwv_flow_themes',
'                         where id                = t.reference_id',
'                           and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'                       ),',
'                       wwv_flow_lang.system_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' )',
'                    )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_themes',
'          where reference_id      = t.id',
'            and security_group_id = :WORKSPACE_ID',
'       ) as subscribers,',
'       ( select count(*) from wwv_theme_page_templates       where current_app_theme_id = t.theme_id ) page_templates,',
'       ( select count(*) from wwv_theme_region_templates     where current_app_theme_id = t.theme_id ) region_templates,',
'       ( select count(*) from wwv_theme_button_templates     where current_app_theme_id = t.theme_id ) button_templates,',
'       ( select count(*) from wwv_theme_breadcrumb_templates where current_app_theme_id = t.theme_id ) menu_templates,',
'       ( select count(*) from wwv_theme_list_templates       where current_app_theme_id = t.theme_id ) list_templates,',
'       ( select count(*) from wwv_theme_item_templates       where current_app_theme_id = t.theme_id ) label_templates,',
'       ( select count(*) from wwv_theme_report_templates     where current_app_theme_id = t.theme_id ) report_templates,',
'       ( select count(*) from wwv_theme_calendar_templates   where current_app_theme_id = t.theme_id ) cal_templates,',
'       ( select count(*) from wwv_theme_popup_lov_templates  where current_app_theme_id = t.theme_id ) popup_templates,',
'       ( select count(*) from wwv_theme_template_components  where current_app_theme_id = t.theme_id ) template_components',
'   from wwv_flow_themes t',
'  where flow_id           = :FB_FLOW_ID',
'    and security_group_id = :FLOW_SECURITY_GROUP_ID )'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
