'       o.name,',
'       o.display_sequence,',
'       o.css_classes,',
'       o.flow_id,',
'       o.security_group_id,',
'       o.theme_id,',
'       o.help_text,',
'       o.group_id,',
'       ( select g.display_sequence from wwv_flow_template_opt_groups g where g.id = o.group_id and g.security_group_id = o.security_group_id ) group_display_sequence,',
'       ( select g.display_name     from wwv_flow_template_opt_groups g where g.id = o.group_id and g.security_group_id = o.security_group_id ) group_display_name',
'  from wwv_flow_template_options o',
' where o.virtual_template_id is null',
'   and ( o.flow_id, o.theme_id, o.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P267_THEME_ID, :WORKSPACE_ID ),',
'        ( ( select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P267_THEME_ID ) from sys.dual ) ,',
'          ( select wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P267_THEME_ID ) from sys.dual ) ,',
