wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(535751771019150805.4008)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Refresh Scripts'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_code          clob;',
'    l_object_types  varchar2(32767);',
'    l_objects       varchar2(32767);',
'    l_owner         wwv_flow_global.t_dbms_id;',
'    l_script_option varchar2(30);',
'begin',
'',
'    for i in 1.. wwv_flow.g_f01.count loop',
'',
'        l_object_types := null;',
'        l_objects := null;',
'        l_owner := null;',
'        l_script_option := null;',
'        l_code := empty_clob;',
'',
'        for c1 in (select script_option',
'                     from wwv_flow_install_scripts',
'                    where security_group_id = :WORKSPACE_ID',
'                      and flow_id = :FB_FLOW_ID',
'                      and id = wwv_flow.g_f01(i) ) loop',
'            l_script_option := c1.script_option;',
'        end loop;',
'',
'        for c1 in (select distinct replace(object_owner,''#''||''OWNER''||''#'',wwv_flow_wizard_api.get_flow_owner) object_owner',
'                     from wwv_flow_install_objects',
'                    where security_group_id = :WORKSPACE_ID',
'                      and flow_id = :FB_FLOW_ID',
'                      and script_id =  wwv_flow.g_f01(i) ) loop',
'',
'            for c2 in (select distinct object_type',
'                         from wwv_flow_install_objects',
'                        where replace(object_owner,''#''||''OWNER''||''#'',wwv_flow_wizard_api.get_flow_owner) = c1.object_owner',
'                          and security_group_id = :WORKSPACE_ID',
'                          and flow_id = :FB_FLOW_ID',
'                          and script_id = wwv_flow.g_f01(i) ) loop',
'                l_object_types := l_object_types||c2.object_type||'':'';',
'            end loop;',
'',
'            for c2 in (select object_name',
'                         from wwv_flow_install_objects',
'                        where replace(object_owner,''#''||''OWNER''||''#'',wwv_flow_wizard_api.get_flow_owner) = c1.object_owner',
'                          and security_group_id = :WORKSPACE_ID',
'                          and flow_id = :FB_FLOW_ID',
'                          and script_id = wwv_flow.g_f01(i) ) loop',
'                l_objects := l_objects||c2.object_name||'':'';',
'            end loop;',
'',
'            if nvl(l_script_option,''x'') in (''PACKAGE_SPEC'',''PACKAGE_BODY'') then',
'                l_object_types := l_script_option;',
'            else',
'                l_object_types := rtrim(l_object_types,'':'');',
'            end if;',
'',
'            l_code := wwv_flow_generate_ddl.get_ddl_supporting_objects(',
'                              p_schema      => c1.object_owner,',
'                              p_object_type => l_object_types,',
'                              p_objects     => rtrim(l_objects,'':''));',
'        end loop;',
'',
'        update wwv_flow_install_scripts',
'           set script = l_code',
'         where security_group_id = :WORKSPACE_ID',
'           and flow_id = :FB_FLOW_ID',
'           and id = wwv_flow.g_f01(i);',
'',
'    end loop;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('\C120\D0DD\D55C \C2A4\D06C\B9BD\D2B8\B97C \C0C8\B85C\ACE0\CE68\D558\B294 \C911 \C624\B958\AC00 \BC1C\C0DD\D588\C2B5\B2C8\B2E4. #SQLERRM#')
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(621103964030076436.4008)
,p_process_success_message=>unistr('\C120\D0DD\D55C \C2A4\D06C\B9BD\D2B8\B97C \B370\C774\D130\BCA0\C774\C2A4 \C18C\C2A4\B85C \C0C8\B85C\ACE0\CE68\D558\C600\C2B5\B2C8\B2E4.')
,p_internal_uid=>535751771019150805.4008
);
end;
