    '   and sf.security_group_id = ps.security_group_id',
    '   and sf.flow_id           = ps.flow_id',
    '   and sf.file_name         = ps.icon_url',
    '   and :p508_file_browse is null',
    '   and :p508_id is not null')))).to_clob
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(11361821035866120.4008)
,p_computation_sequence=>10
,p_computation_item=>'P508_ICON_URL'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_extension varchar2(50);',
'begin',
'    if :P508_FILE_BROWSE_MIME_TYPE like ''%jpeg'' or :P508_FILE_BROWSE_MIME_TYPE like ''%jpg'' then',
'        l_extension := ''jpg'';',
'    else ',
'        l_extension := ''png'';',
'    end if;',
'',
'    return ''pwa/shortcut-icon-''||:p508_display_sequence||''.''||l_extension;',
'end;'))
,p_compute_when=>'P508_FILE_BROWSE_MIME_TYPE'
,p_compute_when_type=>'ITEM_IS_NOT_NULL'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(11360822799866110.4008)
,p_computation_sequence=>10
,p_computation_item=>'P508_INIT_CROPPER_YN'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P508_ID is not null and :P508_ICON_URL is not null then',
'    return ''Y'';',
'end if;',
'',
'for i in ( select 1',
'             from wwv_flow_temp_files ',
'            where name = :p508_file_browse )',
'loop',
'    return ''Y'';',
'end loop;',
'',
'return ''N'';'))
);
