wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1875072844167005.4008)
,p_name=>'P509_AUTH_CONFIG_PROCEDURE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(107178726415706930.4008)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('\AD6C\C131 \D504\B85C\C2DC\C800')
,p_source=>'AUTH_CONFIG_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>32
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\B7F0\D0C0\C784 \C2DC \C778\C99D\C744 \AD6C\C131\D558\B294 \D504\B85C\C2DC\C800\C758 \C774\B984\C744 \C785\B825\D569\B2C8\B2E4.'),
unistr('\C544\B798 \CF54\B4DC\B294 \B2E4\C911 \D14C\B10C\C2DC\B97C \AD6C\D604\D558\ACE0 \D14C\B10C\D2B8\C5D0 \B300\D574 \B2E4\C591\D55C \BCC0\D615\C758'),
unistr('<em>\C18C\C15C \C0AC\C778\C778</em>\C744 \C9C0\C6D0\D558\B294 \C560\D50C\B9AC\CF00\C774\C158\C5D0 \C0AC\C6A9\B429\B2C8\B2E4.'),
unistr('URL\C758 \B3C4\BA54\C778 \C774\B984\C774 \AD6C\C131 \B370\C774\D130 \C778\CD9C\C5D0 \C0AC\C6A9\B429\B2C8\B2E4(URL \C608:'),
'https://cust-01.example.com, https://cust-02.example.com, ...).',
'</p><pre><code>',
'procedure my_auth_config (',
'    p_conf in out nocopy apex_authentication.t_configuration )',
'is',
'    l_host varchar2(32767) := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'begin',
'    for i in ( select discovery_url,',
'                      auth_scheme_name,',
'                      credential,',
'                      tenant_id',
'                 from customer_tenants',
'                where hostname = l_host )',
'    loop',
'        p_conf.authentication_name := i.auth_scheme_name;',
'        p_conf.substitutions := apex_t_varchar2 (',
'                                    ''DISCOVERY_URL''       , i.discovery_url,',
'                                    ''CREDENTIAL_STATIC_ID'', i.credential );',
'        p_conf.tenant_id := i.tenant_id;',
'    end loop;',
'end my_auth_config;',
'</code></pre><p>',
unistr('\D504\B85C\C2DC\C800\B294 \C785\B825/\CD9C\B825 \B9E4\AC1C\BCC0\C218 <code>p_conf</code>\C758 \C18D\C131 \C138 \AC1C\B97C \BCC0\ACBD\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\D574\B2F9 \C18D\C131\C740 \BAA8\B450 \C120\D0DD\C0AC\D56D\C785\B2C8\B2E4.'),
'<ul>',
'    <li><code>authentication_name</code>:',
unistr('    \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \AE30\BCF8 \CCB4\ACC4 \B300\C2E0 \C0AC\C6A9\B420'),
unistr('    \C778\C99D \CCB4\ACC4\C758 \C774\B984\C744 \C9C0\C815\D569\B2C8\B2E4.'),
unistr('    \D574\B2F9 \CCB4\ACC4\C5D0 \B300\D574 <em>\C138\C158\C5D0\C11C \C804\D658</em>\C744 \C0AC\C6A9\C73C\B85C \C124\C815\D574\C57C \D569\B2C8\B2E4.'),
'    </li><li><code>substitutions</code>:',
unistr('    <code>apex_t_varchar2</code>\B97C \C0AC\C6A9\D558\C5EC \C774\B984/\AC12 \C30D\C744 \C9C0\C815\D569\B2C8\B2E4.'),
unistr('    &PRODUCT_NAME.\C740(\B294) \C778\C99D \CCB4\ACC4 \C18D\C131\C758 \AC01 <code>#NAME#</code>\C744(\B97C)'),
unistr('    \C5F0\AD00\B41C \AC12\C73C\B85C \B300\CCB4\D569\B2C8\B2E4.'),
unistr('    \B0B4\C7A5\B41C <em>\C18C\C15C \C0AC\C778\C778</em> \CCB4\ACC4\B294 <code>CREDENTIAL_STATIC_ID</code>\B97C'),
unistr('    \C0AC\C6A9\D558\C5EC \CCB4\ACC4\C5D0\C11C \AD6C\C131\B41C \C800\C7A5\C18C \B300\C2E0 \D574\B2F9\D558\B294 \C778\C99D\C11C \C800\C7A5\C18C\B97C '),
unistr('    \C0AC\C6A9\D569\B2C8\B2E4.'),
'    </li><li><code>tenant_id</code>:',
unistr('    \C138\C158\C5D0\C11C \C774 \D14C\B10C\D2B8 ID\B97C \C124\C815\D569\B2C8\B2E4(<code>apex_session.set_tenant_id</code> \CC38\C870).'),
'    </li>',
'</ul>',
'</p><p>',
unistr('\C778\C99D \AD6C\C131 \D504\B85C\C2DC\C800\B97C \C0AC\C6A9\D558\B294 \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \C778\C99D \CCB4\ACC4\B294'),
unistr('URL(\C608: <code>f?p=100:1:1234:APEX_AUTHENTICATION=myauth</code>)\C744 \D1B5\D574 \BCC0\ACBD\B420 \C218 \C5C6\C2B5\B2C8\B2E4.'),
'</p><p>',
unistr('\C778\C99D \AD6C\C131 \D504\B85C\C2DC\C800\B294 \CCAB\BC88\C9F8 \C694\CCAD \C2DC \C138\C158\B2F9 \D55C \BC88 \C774\C0C1 \C2E4\D589\B429\B2C8\B2E4.    '),
unistr('\B2E8, &PRODUCT_NAME.\C774(\AC00) \B2E4\B978 \C0C1\D669\C5D0\C11C \C774 \D504\B85C\C2DC\C800\B97C \D638\CD9C\D574\C57C \D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.'),
unistr('\C774\B7EC\D55C \ACBD\C6B0 \AC01 \D638\CD9C\C5D0\C11C \B3D9\C77C\D55C \AC12\C744 \C124\C815\D574\C57C \D569\B2C8\B2E4.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
