'<li><code>USER_IS_PUBLIC_USER</code>',
'<li><code>USER_IS_NOT_PUBLIC_USER</code>',
'</ul>',
'<br>',
unistr('<div class="htmldbInfoBodyP">\D604\C7AC \C560\D50C\B9AC\CF00\C774\C158 \C0AC\C6A9\C790(<code>APP_USER</code>)\AC00 \C774 \C18D\C131\C758 \AC12\ACFC \AC19\C740 \ACBD\C6B0 \C0AC\C6A9\C790\B294 \ACF5\AC1C \C0AC\C6A9\C790\B85C \B85C\ADF8\C778\B429\B2C8\B2E4. \C77C\BD80 \C560\D50C\B9AC\CF00\C774\C158\C5D0\B294 \D37C\BE14\B9AD(\B85C\ADF8\C778\D558\C9C0 \C54A\C74C) \BAA8\B4DC\C640 \D504\B77C\C774\BE57(\B85C\ADF8\C778\D568) \BAA8\B4DC\AC00 \C788\C2B5\B2C8\B2E4. \C0AC\C6A9\C790\AC00 \ACF5\AC1C \C0AC\C6A9\C790\C778\C9C0 \D655\C778\D558\C5EC \C815\BCF4\B97C \C870\AC74\BD80\B85C \D45C\C2DC\D558\AC70\B098 \C228\AE38 \C218 \C788\C2B5\B2C8\B2E4.</div>'),
unistr('<div class="htmldbInfoBodyP">\C608\B97C \B4E4\C5B4, \C0AC\C6A9\C790\AC00 \ACF5\AC1C \C0AC\C6A9\C790\C778 \ACBD\C6B0\C5D0\B294 \B85C\ADF8\C778 \B2E8\CD94\B97C, \C0AC\C6A9\C790\AC00 \ACF5\AC1C \C0AC\C6A9\C790\AC00 \C544\B2CC \ACBD\C6B0\C5D0\B294 \B85C\ADF8\C544\C6C3 \B9C1\D06C\B97C \D45C\C2DC\D560 \C218 \C788\C2B5\B2C8\B2E4. PL/SQL \CF54\B4DC\C5D0\C11C <code>APEX_APPLICATION.G_PUBLIC_USER</code> \C804\C5ED \BCC0\C218\B97C \C0AC\C6A9\D558\C5EC \C774 \AC12\C744 \CC38\C870\D558\C2ED\C2DC\C624.</div>'),
unistr('<div class="htmldbInfoBodyP">\B2E4\C74C\C740 <code>APP_USER</code> \CC38\C870\C5D0 \C801\D569\D55C \AD6C\BB38\C758 \C608\C785\B2C8\B2E4.</div>'),
