,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id,',
'       case when (l.locked_by is null) or (l.locked_by is not null and l.locked_by = :APP_USER) then',
'           ''<a href="''',
'           ||wwv_flow_page_api.get_url (',
'                 p_page        => 865,',
'                 p_clear_cache => 865,',
'                 p_items       => ''P865_SCRIPT_ID,P865_MODE,F4000_LAST_VIEW'',',
'                 p_values      => s.id||'',EDIT,667'' )',
'           ||''">''',
'           ||''<img src="#IMAGE_PREFIX#menu/pencil2_16x16.gif" alt="''||sm.edit||''"></a>''',
'       end edit_link,',
'       s.name,',
'       s.sequence,',
'       lower(nvl(s.last_updated_by,s.created_by)) last_updated_by,',
'       nvl(s.last_updated_on, s.created_on) "LAST_UPDATED_ON",',
'       sys.dbms_lob.substr(s.script,200,1)||(case when sys.dbms_lob.getlength(s.script) > 200 then ''...'' end) script,',
'       case when l.locked_by is null then',
'           wwv_flow_lang.system_message(''SCRIPT_NAME_UNLOCKED'', wwv_flow_escape.html(s.name))',
'       else',
'           wwv_flow_lang.system_message(''SCRIPT_NAME_LOCKED'', wwv_flow_escape.html(s.name))',
'       end locked,',
'       case when l.locked_by is null then',
'           ''icon-unlock''',
'       else',
'           ''icon-lock''',
'       end lock_icon,',
'       l.id lock_id',
'  from "#OWNER#"."WWV_FLOW_INSTALL_SCRIPTS" s,',
'       wwv_flow_lock_script l,',
'       (select wwv_flow_lang.system_message(''EDIT'') edit from dual) sm',
' where s.flow_id                    = :FB_FLOW_ID',
'   and s.security_group_id          = :FLOW_SECURITY_GROUP_ID',
'   and s.id                         = l.script_id(+)',
'   and nvl(s.script_type,''INSTALL'') = ''UPGRADE'''))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
