'               p.page_type',
'          from wwv_flow_pages_dev p',
'         where step_template     = :P707_TEMPLATE',
'           and flow_id           = :FB_FLOW_ID',
'           and security_group_id = :FLOW_SECURITY_GROUP_ID) x',
' where :P707_FIND is null',
'    or instr(upper(name),upper(:P707_FIND)) > 0',
