,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select template_name, template_id, button_name, button_label, region, page',
'from',
'(',
'select ',
'  t.TEMPLATE_NAME template_name,',
'  t.id            template_id,',
'  b.BUTTON_NAME   button_name,',
'  b.button_image_alt button_label,',
'  r.plug_name     region,',
'  r.page_id       page',
'from wwv_flow_button_templates t,',
'     wwv_flow_step_buttons b,',
'     wwv_flow_page_plugs r',
' where t.id                =  :P707_TEMPLATE',
'   and t.security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'   and button_template_id  =  t.id',
'   and b.flow_id           =  :FB_FLOW_ID',
'   and b.security_group_id =  :WORKSPACE_ID',
'   and r.id                =  b.button_plug_id',
'   and r.flow_id           =  :FB_FLOW_ID',
'   and r.security_group_id =  :WORKSPACE_ID',
'   and :P707_TEMPLATE_TYPE =  ''BUTTON''',
') x',
'where',
'(',
':P707_FIND is null or ',
'instr(upper(button_name),upper(:P707_FIND)) > 0 or',
'instr(upper(button_label),upper(:P707_FIND)) > 0 or',
'instr(upper(region),upper(:P707_FIND)) > 0 or',
'instr(page,:P707_FIND) > 0',
