,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Distribute Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :P1117_LOCATION = ''LOCAL'' then',
'        case :P1117_QUERY_TYPE',
'            when ''FUNC_BODY_RETURNING_SQL'' then :P1117_QUERY_FUNC_BODY  := :P1117_QUERY_SQL;',
'            when ''GRAPH''                   then :P1117_GRAPH_NAME       := :P1117_QUERY_TABLE;',
'                                                :P1117_PQL_WHERE_CLAUSE := :P1117_QUERY_WHERE;',
'            else null;',
'        end case;',
'    else ',
'        if :P1117_LOCATION = ''REMOTE'' then',
'            :P1117_REMOTE_TABLE_OWNER      := :P1117_QUERY_OWNER;',
'            :P1117_REMOTE_TABLE_NAME       := :P1117_QUERY_TABLE;',
'            :P1117_REMOTE_SOURCE_TYPE      := :P1117_QUERY_TYPE;',
'            :P1117_REMOTE_WHERE            := :P1117_QUERY_WHERE;',
'            :P1117_REMOTE_ORDER_BY         := :P1117_QUERY_ORDER_BY;',
'    ',
'            case :P1117_REMOTE_SOURCE_TYPE',
'                when ''SQL''                     then :P1117_REMOTE_SQL := :P1117_QUERY_SQL;',
'                when ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P1117_REMOTE_FUNC_BODY      := :P1117_QUERY_SQL; ',
'                    :P1117_REMOTE_FUNC_BODY_LANG := :P1117_QUERY_FUNC_LANG;',
'                else null;',
'            end case;',
'',
'        elsif :P1117_LOCATION = ''WEB_SOURCE'' then',
'            :P1117_POST_PROC_TYPE := coalesce( :P1117_SOURCE_POST_PROCESSING, ''NONE'' );    ',
'            :P1117_WEB_SRC_ARRAY_COL_ID := :P1117_ARRAY_COLUMN_ID;        ',
'',
'            if :P1117_POST_PROC_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P1117_POST_PROC_WHERE          := :P1117_QUERY_WHERE;',
'                :P1117_POST_PROC_ORDER_BY       := :P1117_QUERY_ORDER_BY;',
'            elsif :P1117_POST_PROC_TYPE = ''SQL'' then',
'                :P1117_POST_PROC_SQL            := :P1117_QUERY_SQL;',
'            elsif :P1117_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P1117_POST_PROC_FUNC_LANG      := :P1117_QUERY_FUNC_LANG;',
'                :P1117_POST_PROC_FUNC_BODY      := :P1117_QUERY_SQL;',
'            end if;',
'',
'        elsif :P1117_LOCATION = ''DUALITY_VIEW'' then',
'            :P1117_DVPOST_TYPE     := coalesce( :P1117_SOURCE_POST_PROCESSING, ''NONE'' ); ',
'            :P1117_DUALITY_VIEW_ID := :P1117_DOCUMENT_SOURCE_ID;',
'            :P1117_DV_ARRAY_COL_ID := :P1117_ARRAY_COLUMN_ID;',
'',
'            if :P1117_DVPOST_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P1117_DVPOST_WHERE          := :P1117_QUERY_WHERE;',
'                :P1117_DVPOST_ORDER_BY       := :P1117_QUERY_ORDER_BY;',
'            elsif :P1117_DVPOST_TYPE = ''SQL'' then',
'                :P1117_DVPOST_SQL            := :P1117_QUERY_SQL;',
'            elsif :P1117_DVPOST_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P1117_DVPOST_FUNC_LANG      := :P1117_QUERY_FUNC_LANG;',
'                :P1117_DVPOST_FUNC_BODY      := :P1117_QUERY_SQL;',
'            end if;  ',
'',
'        elsif :P1117_LOCATION = ''JSON_COLLECTION'' then',
'            :P1117_JSON_SOURCE_ID  := :P1117_DOCUMENT_SOURCE_ID;',
'            :P1117_JSPOST_TYPE     := coalesce( :P1117_SOURCE_POST_PROCESSING, ''NONE'' );            ',
'            :P1117_JS_ARRAY_COL_ID := :P1117_ARRAY_COLUMN_ID;',
'',
'            if :P1117_JSPOST_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P1117_JSPOST_WHERE          := :P1117_QUERY_WHERE;',
'                :P1117_JSPOST_ORDER_BY       := :P1117_QUERY_ORDER_BY;',
'            elsif :P1117_JSPOST_TYPE = ''SQL'' then',
'                :P1117_JSPOST_SQL            := :P1117_QUERY_SQL;',
'            elsif :P1117_JSPOST_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P1117_JSPOST_FUNC_LANG      := :P1117_QUERY_FUNC_LANG;',
'                :P1117_JSPOST_FUNC_BODY      := :P1117_QUERY_SQL;',
'            end if;                        ',
'',
'        end if;',
'',
'        :P1117_QUERY_SQL        := null;',
'        :P1117_QUERY_TABLE      := null;',
'        :P1117_QUERY_OWNER      := null;',
'        :P1117_QUERY_WHERE      := null;',
'        :P1117_QUERY_ORDER_BY   := null;',
'        :P1117_QUERY_TYPE       := null;',
'    end if;',
'end;'))
