,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4008)
,p_plug_display_sequence=>141
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select l.id,',
'       l.report_layout_name,',
'       l.report_layout_type,',
'       l.last_updated_on,',
'       ''icon-sc-report-layout'' icon_class,',
'       wwv_flow_page_api.get_url(',
'           p_page        => 1405,',
'           p_clear_cache => 1405,',
'           p_items       => ''P1405_ID'',',
'           p_values      => l.id ) edit_link,',
'       replace(replace(l.report_layout_name,''_'','' ''),''.'','' '') icon_title,',
'       --',
'       case when l.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_report_layouts sub',
'          where sub.reference_id      = l.id',
'            and sub.security_group_id = :WORKSPACE_ID',
'       ) as subscribers,',
'       case when l.reference_id is not null then',
'           case',
'               when master.version_scn = l.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != l.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,',
'       --',
'       null as actions,',
'       case',
'         when    (  :F4000_PRINT_SERVER_TYPE = ''STANDARD'' ',
'                and l.report_layout_type in ( ''XSL_GENERIC'', ''XSL_FILE'' ) )',
'              or (  :F4000_PRINT_SERVER_TYPE = ''ADVANCED'' ',
'                and l.report_layout_type in ( ''XSL_GENERIC'', ''XSL_FILE'', ''RTF_FILE'' ) )',
'              or (  :F4000_PRINT_SERVER_TYPE = ''DOCUMENT_GENERATOR'' ',
'                and l.report_layout_type in ( ''DOCX_FILE'', ''XLSX_FILE'' ) )',
'              or (  :F4000_PRINT_SERVER_TYPE = ''AOP'' ',
'                and l.report_layout_type not in ( ''XSL_GENERIC'', ''XSL_FILE'' ) )',
'         then ''Y'' ',
'         else ''N''',
'       end as is_compatible',
'  from wwv_flow_report_layouts l,',
'       wwv_flow_report_layouts master',
' where l.flow_id                = :FB_FLOW_ID',
'   and l.security_group_id      = :WORKSPACE_ID',
'   and l.reference_id           = master.id (+)',
'   and l.security_group_id      = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
