,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p><strong>REST \C0AC\C6A9 SQL</strong> \C11C\BE44\C2A4\B97C \C0DD\C131\D558\C5EC \C6D0\ACA9 Oracle \B370\C774\D130\BCA0\C774\C2A4\C758 &PRODUCT_NAME. \AD6C\C131\C694\C18C\C5D0\C11C \C815\C758\B41C SQL \B610\B294 PL/SQL\C744 \C2E4\D589\D569\B2C8\B2E4.'),
'',
unistr('</p><p><strong>\C694\AD6C\C0AC\D56D:</strong> \C6D0\ACA9 \B370\C774\D130\BCA0\C774\C2A4\C758 \D504\B860\D2B8 \C5D4\B4DC\C5D0 ORDS(Oracle REST Data Services) \B9B4\B9AC\C2A4 20.3 \B610\B294 \C774\D6C4 \BC84\C804\C774 \D3EC\D568\B418\C5B4\C57C \D558\BA70 <em>REST \C0AC\C6A9 SQL</em> \AE30\B2A5\C774 \C0AC\C6A9\C73C\B85C \C124\C815\B418\C5B4\C57C \D569\B2C8\B2E4. \BAA8\B4E0 SQL \BC0F PL/SQL\C774 ORDS \C778\C2A4\D134\C2A4\B85C \C804\C1A1\B418\C5B4 \C6D0\ACA9 \B370\C774\D130\BCA0\C774\C2A4\C5D0\C11C \C2E4\D589\B429\B2C8\B2E4. </p>'),
'',
unistr('<p>REST \C0AC\C6A9 SQL \CC38\C870\B294 \C791\C5C5\C601\C5ED \B808\BCA8\C5D0\C11C \C800\C7A5\B418\BBC0\B85C \BAA8\B4E0 \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \D45C\C2DC\B429\B2C8\B2E4.</p>'),
'',
unistr('<p>\C560\D50C\B9AC\CF00\C774\C158\C744 \C775\C2A4\D3EC\D2B8\D558\BA74 \C0AC\C6A9\B41C REST \C0AC\C6A9 SQL \CC38\C870\AC00 \C775\C2A4\D3EC\D2B8 \D30C\C77C\C5D0 \CD94\AC00\B429\B2C8\B2E4. \C560\D50C\B9AC\CF00\C774\C158\C744 \C775\C2A4\D3EC\D2B8\D55C \D6C4 \B2E4\B978 \C791\C5C5\C601\C5ED\C73C\B85C \C784\D3EC\D2B8\D558\BA74 &PRODUCT_NAME.\C740(\B294) \B3D9\C77C\D55C <strong>\C815\C801 ID</strong>\B97C \C0AC\C6A9\D558\B294 REST \C0AC\C6A9 SQL \CC38\C870\AC00 \B300\C0C1 \C791\C5C5\C601\C5ED\C5D0 \C774\BBF8 \D3EC\D568\B418\C5B4 \C788\B294\C9C0 \C5EC\BD80\B97C \D655\C778\D569\B2C8\B2E4. REST \C0AC\C6A9 SQL \CC38\C870\AC00 \C874\C7AC\D558\B294 \ACBD\C6B0 \C560\D50C\B9AC\CF00\C774\C158\C740 \AE30\C874 \CC38\C870\B97C \C0AC\C6A9\D569\B2C8\B2E4. \CC38\C870\AC00 \C874\C7AC\D558\C9C0 \C54A\C744 \ACBD\C6B0 \B300\C0C1 ')
||unistr('\C791\C5C5\C601\C5ED\C5D0 \C0DD\C131\B429\B2C8\B2E4.</p>')))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
