,p_item_plug_id=>wwv_flow_imp.id(2002487147223122.4008)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('\AD6C\C131 \D504\B85C\C2DC\C800')
,p_source=>'CONFIGURATION_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>59
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\B7F0\D0C0\C784\C5D0 \B05D\C810 URL\C744 \AD6C\C131\D558\B294 \D504\B85C\C2DC\C800\C758 \C774\B984\C744 \C785\B825\D569\B2C8\B2E4.'),
unistr('\C774\B294 \B0B4\C7A5 \D504\B85C\C2DC\C800\C774\AC70\B098 <em>PL/SQL \CF54\B4DC</em> \D56D\BAA9\C5D0 \C815\C758\B41C \D504\B85C\C2DC\C800\C77C \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\C544\B798 \CF54\B4DC\B294 \B2E4\C911 \D14C\B10C\C2DC\B97C \AD6C\D604\D558\ACE0 \D14C\B10C\D2B8\B9C8\B2E4 <em>\B05D\C810 URL</em>\C758'),
unistr('\B2E4\C591\D55C \BCC0\D615\C744 \C9C0\C6D0\D558\B294 \C560\D50C\B9AC\CF00\C774\C158\C744 \C704\D55C \AC83\C785\B2C8\B2E4.'),
unistr('\ACE0\AC1D\C5D0 \B530\B77C URL\C758 \B3C4\BA54\C778 \C774\B984\C744 \BCC0\ACBD\D569\B2C8\B2E4. (\C608\C81C URL: '),
'https://cust-01.example.com, https://cust-02.example.com):',
'</p><pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
'end;',
'</code></pre><p>',
