wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3052579561518938945.4008)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Test ORDS Remote SQL Server'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_base_url    varchar2(32767);',
'    l_test_result wwv_flow_exec_remote.t_server_test_result;',
'begin',
'',
'    -- first test if a configuration procedure for the server is working',
'    l_base_url := wwv_flow_exec_remote.get_configured_base_url(',
'          p_remote_server_id => :P1605_ID,',
'          p_application_id   => null );',
'',
'    wwv_flow_exec_remote.test_remote_sql_server(',
'        p_remote_server_id => :P1605_ID,',
'        p_test_result      => l_test_result );',
'',
'    :P1605_SQL_RESPONSE     := l_test_result.message;',
'    :P1605_SQLCODE          := l_test_result.sql_error_code;',
'    :P1605_HTTP_STATUS      := l_test_result.http_status_code;',
'    :P1605_SERVER_STATUS    := l_test_result.server_status;',
'',
'    :P1605_DATABASE_TYPE    := case l_test_result.remote_server.database_type',
'                                   when wwv_flow_exec_api.c_database_oracle then ''ORACLE''',
'                                   when wwv_flow_exec_api.c_database_mysql  then ''MYSQL''',
'                               end;',
'    :P1605_DEFAULT_DATABASE := l_test_result.remote_server.default_schema;',
'    :P1605_DATABASE_VERSION := l_test_result.remote_server.database_version;',
'    :P1605_MYSQL_SQL_MODES  := replace( l_test_result.mysql_sql_modes, '','', '', '' );',
'',
'    :P1605_ENDPOINT_URL     := l_base_url;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>3052579561518938945.4008
);
end;
