wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2992187177431212.4008)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adjust DB Credential Items on Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    :P1621_USE_DB_CREDENTIAL := case when :P1621_DB_CREDENTIAL_NAME is not null then ''Y'' else ''N'' end;',
'',
'    if :P1621_DB_CRED_IS_INSTANCE = ''Y'' then',
'        :P1621_INSTANCE_DB_CRED_NAME := :P1621_DB_CREDENTIAL_NAME;',
'        :P1621_SCHEMA_DB_CRED_NAME   := null;',
'    else ',
'        :P1621_INSTANCE_DB_CRED_NAME := null;',
'        :P1621_SCHEMA_DB_CRED_NAME   := :P1621_DB_CREDENTIAL_NAME;',
'    end if;',
'',
'    :P1621_DB_CREDENTIAL_TYPE := case :P1621_DB_CRED_IS_INSTANCE ',
'                                     when ''Y'' then ''INSTANCE''',
'                                     when ''N'' then ''SCHEMA''',
'                                 end;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'wwv_flow_db_version.c_has_utl_http_credential'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>2992187177431212.4008
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1703466871678417.4008)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Client ID / Client Secret when not displayed'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case :P1621_CREDENTIALS_TYPE',
'when ''OCI'' then',
'    :P1621_CLIENT_ID := nvl(:P1621_OCI_USER_ID     ,:P1621_CLIENT_ID);',
'    :P1621_SECRET    := nvl(:P1621_OCI_PRIVATE_KEY ,:P1621_SECRET);',
'when ''CERTIFICATE_PAIR'' then',
'    :P1621_CLIENT_ID := nvl(:P1621_CERTIFICATE     ,:P1621_CLIENT_ID);',
'    :P1621_SECRET    := nvl(:P1621_CERT_PRIVATE_KEY,:P1621_SECRET);',
'when ''HTTP_HEADER'' then',
'    :P1621_CLIENT_ID := nvl(:P1621_GENERIC_NAME,    :P1621_CLIENT_ID);',
'    :P1621_SECRET    := nvl(:P1621_GENERIC_VALUE,   :P1621_SECRET);',
'when ''HTTP_QUERY_STRING'' then',
'    :P1621_CLIENT_ID := nvl(:P1621_GENERIC_NAME,    :P1621_CLIENT_ID);',
'    :P1621_SECRET    := nvl(:P1621_GENERIC_VALUE,   :P1621_SECRET);',
'when ''KEY_PAIR'' then',
'    :P1621_CLIENT_ID     := nvl(:P1621_PUBLIC_KEY,         :P1621_CLIENT_ID);',
'    :P1621_SECRET        := nvl(:P1621_PRIVATE_KEY,        :P1621_SECRET);',
'end case;',
'',
'case :P1621_CREDENTIALS_TYPE',
'when ''KEY_PAIR'' then',
'    :P1621_SECRET_VERIFY := :P1621_PRIVATE_KEY_VERIFY;',
'else',
'    :P1621_SECRET_VERIFY := :P1621_SECRET;',
'end case;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P1621_CREDENTIALS_TYPE'
,p_process_when_type=>'VALUE_OF_ITEM_IN_CONDITION_IN_COLON_DELIMITED_LIST'
,p_process_when2=>'OCI:CERTIFICATE_PAIR:HTTP_HEADER:HTTP_QUERY_STRING:KEY_PAIR'
,p_internal_uid=>1703466871678417.4008
);
end;
