,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_server_id         number;',
'begin',
'    insert into wwv_remote_servers (',
'        name,',
'        static_id,',
'        base_url,',
'        server_type,',
'        prompt_on_install,',
'        credential_id',
'    ) values (',
'        :P1850_NAME,',
'        :P1850_STATIC_ID,',
'        :P1850_BASE_URL||:P1850_BUCKET_NAME||''/o/'',',
'        ''CLOUD_OBJECT_STORE'',',
'        ''Y'',',
'        :P1850_CREDENTIAL_ID',
'        )',
'    returning id into l_server_id;',
'',
'    update wwv_flows',
'       set file_storage           = ''OBJECT_STORE'',',
'           file_remote_server_id  = l_server_id',
'     where id                     = :FB_FLOW_ID',
'       and security_group_id      = :FLOW_SECURITY_GROUP_ID;',
'',
'    if wwv_flow_collection.collection_exists(''F4000_OB_FILES'') then',
'        wwv_flow_collection.delete_collection(''F4000_OB_FILES'');',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P1851_RESULT'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
