,p_plug_name=>unistr('\C778\C99D')
,p_region_template_options=>'#DEFAULT#:a-Alert--noIcon:a-Alert--info:a-Alert--horizontal'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4008)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null ',
'  from wwv_web_src_catalog_services cs,',
'       wwv_flow_collections         so',
' where cs.id                = so.n001',
'   and cs.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and cs.authentication_type is not null',
'   and so.collection_name   = ''REST_CATALOG_SELECTIONS''',
'   and so.c002              = ''CATALOG'''))
,p_plug_header=>unistr('<p>\C120\D0DD\D55C \CE74\D0C8\B85C\ADF8 \C11C\BE44\C2A4 \C911 \C77C\BD80\C5D0 \C778\C99D\C774 \D544\C694\D569\B2C8\B2E4. \AE30\C874 <strong>\C6F9 \C778\C99D\C11C</strong>\B97C \C120\D0DD\D558\AC70\B098 &PRODUCT_NAME.\C774(\AC00) \C0C8\B85C \C0DD\C131\D558\B3C4\B85D \D569\B2C8\B2E4.</p>')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
