wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3292574859489450.4008)
,p_name=>'P1921_WEB_SOURCE_TYPE'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(3292099913489445.4008)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('REST \B370\C774\D130 \C18C\C2A4 \C720\D615')
,p_source=>'WEB_SOURCE_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_MODULE_TYPES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''WEB_SOURCE.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''WEB SOURCE TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''WEB SOURCE TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4008)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('REST \B370\C774\D130 \C18C\C2A4 \C720\D615\C744 \ACB0\C815\D569\B2C8\B2E4.'),
'<ul>',
unistr('<li><strong>\B2E8\C21C HTTP</strong>\B294 \B2E8\C21C HTTP \B370\C774\D130 \D53C\B4DC\B97C \B098\D0C0\B0C5\B2C8\B2E4. &PRODUCT_NAME.\C740(\B294) \CCAB\BC88\C9F8 \C694\CCAD\C73C\B85C \BAA8\B4E0 \B370\C774\D130\AC00 \BC18\D658\B418\BA70 \C11C\BC84\AC00 \C11C\BC84\CE21 \D544\D130\B9C1, \C815\B82C \B610\B294 \AE30\D0C0 \ACE0\AE09 REST \C11C\BE44\C2A4 \AE30\B2A5\C744 \C9C0\C6D0\D558\C9C0 \C54A\B294\B2E4\ACE0 \AC00\C815\D569\B2C8\B2E4. \BAA8\B4E0 \D638\CD9C \C138\BD80\C815\BCF4 \BC0F \B9E4\AC1C\BCC0\C218\B294 \C218\B3D9\C73C\B85C \AD6C\C131\D574\C57C \D569\B2C8\B2E4.</li>'),
unistr('<li><strong>ORDS(Oracle REST Data Services)</strong>\B294 ORDS\AC00 \C81C\ACF5\D558\B294 RESTful \C11C\BE44\C2A4\B97C \B098\D0C0\B0C5\B2C8\B2E4. \D574\B2F9 REST \C11C\BE44\C2A4\B294 <em>Oracle REST \D45C\C900</em>\C744 \B530\B974\BA70, \C774\B294 GET, POST, PUT \B610\B294 DELETE \C791\C5C5\C774 \D45C\C900\D654\B428\C744 \C758\BBF8\D569\B2C8\B2E4. \C11C\BC84\CE21 \D544\D130\B9C1 \BC0F \C815\B82C\C774 \C9C0\C6D0\B429\B2C8\B2E4. &PRODUCT_NAME.\C740(\B294) \BCF4\ACE0\C11C \C815\B82C \AE30\C900 \BC0F \D544\D130\B97C REST \C11C\BE44\C2A4\C5D0 \C704\C784\D558\C5EC \C774\B7EC\D55C \AE30\B2A5')
||unistr('\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>REST \C0AC\C6A9 SQL \C9C8\C758</strong>\B294 REST \C0AC\C6A9 SQL \CC38\C870\C5D0\C11C \C2E4\D589\B418\B294 SQL \C9C8\C758 \C704\C5D0\C11C REST \C18C\C2A4\B97C \B098\D0C0\B0C5\B2C8\B2E4. &PRODUCT_NAME.\C740(\B294) \D544\D130\B9C1 \BC0F \D398\C774\C9C0 \B9E4\AE40\C744 \C9C0\C6D0\D558\C9C0\B9CC \C774\B7EC\D55C \B05D\C810\C5D0\C11C DML\C744 \C9C0\C6D0\D558\C9C0 \C54A\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>Oracle Cloud Applications(SaaS) REST \C11C\BE44\C2A4</strong>\B294 Oracle Cloud Applications(SaaS)\AC00 \C81C\ACF5\D558\B294 RESTful \C11C\BE44\C2A4\B97C \B098\D0C0\B0C5\B2C8\B2E4. \C774 \C6F9 \C11C\BE44\C2A4 \C720\D615\C744 \C0AC\C6A9\D558\C5EC Oracle SaaS REST \C11C\BE44\C2A4\B97C &PRODUCT_NAME. \C560\D50C\B9AC\CF00\C774\C158\C5D0 \D1B5\D569\D560 \C218 \C788\C2B5\B2C8\B2E4. &PRODUCT_NAME.\C740(\B294) \D574\B2F9 \C11C\BE44\C2A4\C5D0 \B300\D574 \D398\C774\C9C0 \B9E4\AE40\C744 \C9C0\C6D0\D569\B2C8\B2E4.</li>'),
