,p_post_element_text=>unistr('<a id="P1922_GENERATE_BODY_TEMPLATE" class="a-Button a-Button--noLabel a-Button--small a-Button--withIcon" href="#"><span class="a-Icon icon-refresh"></span> \C0DD\C131</a>')
,p_source=>'REQUEST_BODY_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>100
,p_cMaxlength=>32760
,p_cHeight=>8
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    HTTP POST, PUT, PATCH or DELETE \C694\CCAD\C5D0 \C0AC\C6A9\D560 \C694\CCAD \BCF8\BB38 \D15C\D50C\B9AC\D2B8\B97C \C785\B825\D569\B2C8\B2E4. \D15C\D50C\B9AC\D2B8 \B0B4\C5D0 \C704\CE58 \D45C\C2DC\C790(<em>#placeholder-name#</em>)\B97C \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. <strong>!RAW</strong> \C218\C815\C790\B97C \C0AC\C6A9\D558\BA74 &PRODUCT_NAME.\C774(\AC00) \B300\CCB4\B97C \C218\D589\D560 \B54C \C774\C2A4\CF00\C774\D504\B97C \C228\AE38 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('    <strong>!NULL</strong> \C218\C815\C790\B97C \C0AC\C6A9\D558\BA74 \BE44\C5B4 \C788\B294 \AC12\C744 <strong>null</strong> JSON \D0A4\C6CC\B4DC\B85C \BC14\AFC0 \C218 \C788\C2B5\B2C8\B2E4.'),
'</p>',
'<ul>',
unistr('    <li><strong>\C694\CCAD/\C751\B2F5 \BCF8\BB38</strong> \C720\D615\C758 REST \C18C\C2A4 \B9E4\AC1C\BCC0\C218\C758 \ACBD\C6B0 \BAA8\B4E0 \C791\C5C5\C5D0 \B300\D574 \C704\CE58 \D45C\C2DC\C790\AC00 \C2E4\D589\B429\B2C8\B2E4.</li>'),
unistr('    <li>\B370\C774\D130 \D504\B85C\D30C\C77C \C5F4\C758 \ACBD\C6B0 \D589 \C0BD\C785, \D589 \C5C5\B370\C774\D2B8 \B610\B294 \D589 \C0AD\C81C \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C744 \C2E4\D589\D560 \B54C \C704\CE58 \D45C\C2DC\C790\AC00 \BC14\B01D\B2C8\B2E4.</li>'),
'</ul> ',
'<p>',
'    <br>',
unistr('    \C790\B3D9 DML \D504\B85C\C138\C2A4(REST \C11C\BE44\C2A4\C758 \D3FC \C601\C5ED)\B294 \C704\CE58 \D45C\C2DC\C790\B97C <em>data-type aware, quoted and escaped</em> \AC12\C73C\B85C \BC14\AFC9\B2C8\B2E4. \C0AC\C6A9\C790\C815\C758 PL/SQL \D504\B85C\C138\C2A4(APEX_EXEC.EXECUTE_WEB_SOURCE\AC00 \C0AC\C6A9\B41C \ACBD\C6B0)\B294 \C77C\BC18 \C704\CE58 \D45C\C2DC\C790\B97C \C774\C2A4\CF00\C774\D504 \CC98\B9AC\B41C \BB38\C790\C5F4 \AC12\C73C\B85C \BC14\AFC9\B2C8\B2E4. <strong>!RAW</strong> \C218\C815\C790\AC00 \C788\B294 \C704\CE58 \D45C\C2DC\C790\B294 \C774\C2A4\CF00\C774\D504 \CC98\B9AC\B418\C9C0 \C54A\C740 \AC12\C73C\B85C \BC14\B01D\B2C8\B2E4. ')
||unistr('\B530\B77C\C11C APEX_EXEC.EXECUTE_WEB_SOURCE\C5D0 \C0AC\C6A9\D560 \ACBD\C6B0 \D15C\D50C\B9AC\D2B8\C5D0\C11C \C704\CE58 \D45C\C2DC\C790\B97C \B530\C634\D45C\B85C \BB36\C5B4\C57C \D569\B2C8\B2E4. \C120\C5B8 \D3FC\ACFC \D568\AED8 \C0AC\C6A9\D560 \ACBD\C6B0 \C704\CE58 \D45C\C2DC\C790\B97C \B530\C634\D45C\B85C \BB36\C9C0 \C54A\C544\C57C \D558\BA70 \AC12\C740 \D56D\C0C1 \C774\C2A4\CF00\C774\D504 \CC98\B9AC\B429\B2C8\B2E4.'),
'</p>',
'<p>',
unistr('    \C694\CCAD \BCF8\BB38 \D15C\D50C\B9AC\D2B8 \C608: \AC1D\CCB4\B97C \C804\B2EC\D558\B294 \B2E8\C21C\D55C JSON \AD6C\C870\C785\B2C8\B2E4. \D589 \C0BD\C785, \D589 \C5C5\B370\C774\D2B8 \B610\B294 \D589 \C0AD\C81C \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C758 \ACBD\C6B0 \C704\CE58 \D45C\C2DC\C790\AC00 \B370\C774\D130 \D504\B85C\D30C\C77C \C5F4\B85C \BC14\B01D\B2C8\B2E4. REST \B370\C774\D130 \C18C\C2A4\B294 \D3FC \C601\C5ED\ACFC \D568\AED8 \C0AC\C6A9\B418\BBC0\B85C, \C704\CE58 \D45C\C2DC\C790\B97C \B530\C634\D45C\B85C \BB36\C9C0 \C54A\C2B5\B2C8\B2E4.'),
'</p>',
'<pre>',
'{"empno": #EMPNO#, "ename": #ENAME#, "job": #JOB#, "sal": #SAL#, "comm": #COMM#, "hiredate": #HIREDATE#, "deptno": #DEPTNO#}',
'</pre>',
'<p>',
unistr('    \C694\CCAD \BCF8\BB38 \D15C\D50C\B9AC\D2B8 \C608: \AC1D\CCB4\B97C \C804\B2EC\D558\B294 \BCF4\B2E4 \BCF5\C7A1\D55C JSON \AD6C\C870\C785\B2C8\B2E4. \D589 \C0BD\C785, \D589 \C5C5\B370\C774\D2B8 \B610\B294 \D589 \C0AD\C81C \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C758 \ACBD\C6B0 \C704\CE58 \D45C\C2DC\C790\AC00 \B370\C774\D130 \D504\B85C\D30C\C77C \C5F4\B85C \BC14\B01D\B2C8\B2E4. REST \B370\C774\D130 \C18C\C2A4\B294 \C0AC\C6A9\C790\C815\C758 PL/SQL\ACFC \D568\AED8 \C0AC\C6A9\B418\BBC0\B85C, \C704\CE58 \D45C\C2DC\C790\B97C \B530\C634\D45C\B85C \BB36\C2B5\B2C8\B2E4. \CD94\AC00 \C704\CE58 \D45C\C2DC\C790\B97C <strong>REST \C18C\C2A4 \B9E4\AC1C\BCC0\C218</strong>\C5D0 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \BAA8\B4C8 \B610\B294 \C791\C5C5 \B808\BCA8\C5D0\C11C <strong>\C694\CCAD/\C751\B2F5 \BCF8\BB38</s')
||unistr('trong> \C720\D615\C758 \B9E4\AC1C\BCC0\C218\B85C \C815\C758\D574\C57C \D569\B2C8\B2E4.'),
'</p>',
'<pre>',
'{ "passed-by": "#USERID#",',
'  "client-id": "APEX-#APEX_INSTANCE#",',
'  "object": {',
'      "empno": #EMPNO#, ',
'      "ename": "#ENAME#", ',
'      "job": "#JOB#", ',
'      "sal": #SAL#, ',
'      "comm": #COMM#, ',
'      "hiredate": "#HIREDATE#", ',
'      "deptno": #DEPTNO# } }',
'</pre>',
'<p>',
unistr('    REST \B370\C774\D130 \C18C\C2A4 \C815\C758 \B0B4\C758 <em>\B370\C774\D130 \D504\B85C\D30C\C77C</em>\C5D0\C11C \C694\CCAD \BCF8\BB38 \D15C\D50C\B9AC\D2B8\B97C \C0DD\C131\D558\B824\BA74 <strong><span class="a-Icon icon-refresh"></span> \C0DD\C131</strong> \B2E8\CD94\B97C \B204\B974\C2ED\C2DC\C624(\D14D\C2A4\D2B8 \C601\C5ED\C774 \BE44\C5B4 \C788\C744 \B54C\B9CC \B2E8\CD94\AC00 \B098\D0C0\B0A8).'),
'</p>',
''))
