,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    REST \C6F9 \C11C\BE44\C2A4\C5D0\C11C \C2E4\D589\D560 HTTP \C791\C5C5 \B610\B294 <em>\BA54\C18C\B4DC</em>(GET, POST, PUT, DELETE)\C785\B2C8\B2E4. URL \D328\D134\ACFC HTTP \C791\C5C5\C758 \C870\D569\C73C\B85C REST \B370\C774\D130 \C18C\C2A4 \B0B4\C758 \C791\C5C5\C744 \C2DD\BCC4\D560 \C218 \C788\C2B5\B2C8\B2E4. REST \B370\C774\D130 \C18C\C2A4\C5D0\B294 \B2E4\B978 HTTP \C791\C5C5\C5D0 \B3D9\C77C\D55C URL \D328\D134\C744 \D3EC\D568\D558\ACE0 \B3D9\C77C\D55C HTTP \C791\C5C5\C5D0 \B2E4\B978 URL \D328\D134\C744 \D3EC\D568\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
'</p>',
'<p>',
unistr('    \B2E4\C74C\C740 REST \C11C\BE44\C2A4\C5D0\C11C HTTP \BA54\C18C\B4DC\C640 \C0AC\C6A9\BC95\C5D0 \B300\D55C \AC04\B7B5\D55C \C124\BA85\C785\B2C8\B2E4. \C774 \BAA8\B4E0 \AC83\C740 \ADDC\C57D\C785\B2C8\B2E4. REST \C11C\BE44\C2A4\B294 \C774\B97C \C900\C218\D574\C57C \D558\C9C0\B9CC \C2E4\C81C \AD6C\D604\C740 \B2E4\B97C \C218 \C788\C2B5\B2C8\B2E4. \D638\CD9C \AC00\B2A5\D55C \BA54\C18C\B4DC\C640 \C791\B3D9 \BC29\BC95\C744 \C54C\C544\BCF4\B824\BA74 \C561\C138\C2A4\D558\B824\B294 REST \C11C\BE44\C2A4\C758 \C124\BA85\C11C\B97C \D56D\C0C1 \D655\C778\D558\C2ED\C2DC\C624.'),
'</p>',
