,p_validation_name=>'Validate REST Operation integrity rules'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'return wwv_flow_web_src_dev.validate_web_src_operations(',
'           p_security_group_id      => :FLOW_SECURITY_GROUP_ID,',
'           p_flow_id                => :FB_FLOW_ID,',
'           p_web_src_module_id      => :P1922_WEB_SRC_MODULE_ID,',
'           p_dml_operation          => case :REQUEST',
'                                           when ''CREATE'' then wwv_flow_exec_api.c_dml_operation_insert',
'                                           when ''SAVE''   then wwv_flow_exec_api.c_dml_operation_update',
'                                           when ''DELETE'' then wwv_flow_exec_api.c_dml_operation_delete',
'                                       end,',
'           p_operation_id           => :P1922_ID,',
'           p_static_id              => :P1922_STATIC_ID,',
'           p_url_pattern            => :P1922_URL_PATTERN,',
'           p_operation              => :P1922_REST_OPERATION,',
'           p_database_operation     => :P1922_DATABASE_OPERATION,',
'           p_array_column_id        => :P1922_DATA_PROFILE_ARRAY_ID );'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'CREATE,SAVE,DELETE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(987817675354252924.4008)
,p_validation_name=>'Validate Calendaring Expression'
,p_validation_sequence=>60
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_next_run_timestamp timestamp with time zone;',
'    l_minutes            number;',
'begin',
'    begin',
'        l_minutes := to_number( :P1922_INVALIDATE_WHEN );',
'        return null;',
'    exception',
'        -- if not a number, then proceed with validating the calendaring expression',
'        when others then null;',
'    end;',
'',
'    begin',
'        sys.dbms_scheduler.evaluate_calendar_string(',
'            calendar_string   => :P1922_INVALIDATE_WHEN,',
'            start_date        => systimestamp,',
'            return_date_after => systimestamp,',
'            next_run_date     => l_next_run_timestamp );',
'    exception',
'        when others then',
'            return sqlerrm;',
'    end;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>':P1922_CACHING is not null and :REQUEST in (''CREATE'', ''SAVE'' )'
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(3507960502076974.4008)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
