wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(529291815946976412.4008)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Rediscover'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_uploaded_file blob;',
'    l_json_schema   clob;',
'',
'    l_file_item     varchar2(255);',
'begin',
'    l_file_item := case :P1925_DATA_PROFILE_FOR',
'                       when ''REST_SOURCE'' then :P1925_SAMPLE_RESPONSE',
'                       when ''DOC_SOURCE''  then :P1925_JSON_SCHEMA_RESPONSE',
'                   end;',
'',
'    if l_file_item is not null then',
'        select blob_content',
'          into l_uploaded_file',
'          from wwv_flow_temp_files',
'         where name = l_file_item;',
'    end if;',
'        ',
'    if :P1925_DATA_PROFILE_FOR = ''REST_SOURCE'' then',
'        wwv_flow_web_src_dev.rediscover( ',
'            p_web_src_module_id => :P1921_WEB_SRC_MODULE_ID,',
'            p_sample_response   => l_uploaded_file );',
'',
'    elsif  :P1925_DATA_PROFILE_FOR = ''DOC_SOURCE'' then',
'',
'        if l_uploaded_file is not null then',
'            l_json_schema := wwv_flow_utilities.blob_to_clob( l_uploaded_file );',
'        end if;',
'',
'        wwv_flow_doc_src_dev.rediscover( ',
'            p_document_source_id => :P7110_ID,',
'            p_json_schema        => l_json_schema );',
'',
'    end if;',
'exception',
'when others then',
'wwv_flow_debug.log_exception;',
'raise;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST = ''APPLY_CHANGES_REDISCOVER'' and :P1925_DATA_PROFILE_FOR in (''REST_SOURCE'', ''DOC_SOURCE'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>529291815946976412.4008
);
