,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>REST \B370\C774\D130 \C18C\C2A4 \C11C\BC84 \C815\BCF4\B294 <strong>\C6D0\ACA9 \C11C\BC84</strong> \AC1D\CCB4\B85C \C800\C7A5\B429\B2C8\B2E4. \C6D0\ACA9 \C11C\BC84\B294 \C5EC\B7EC REST \B370\C774\D130 \C18C\C2A4\C5D0\C11C \ACF5\C720\B420 \C218 \C788\C2B5\B2C8\B2E4. \C6D0\ACA9 \C11C\BC84 \C18D\C131\C744 \BCC0\ACBD\D558\BA74 \D574\B2F9 \AC1D\CCB4\B97C \CC38\C870\D558\B294 \BAA8\B4E0 REST \B370\C774\D130 \C18C\C2A4\AC00 \C601\D5A5\C744 \BC1B\C2B5\B2C8\B2E4. \C608\B97C \B4E4\C5B4, \C6D0\ACA9 \C11C\BC84 \AC1D\CCB4\B97C \D14C\C2A4\D2B8\C5D0\C11C \C6B4\C6A9 \C2DC\C2A4\D15C\C73C\B85C \BCC0\ACBD\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p>\C6D0\ACA9 \C11C\BC84\B294 \C791\C5C5\C601\C5ED \B808\BCA8\C5D0\C11C \C800\C7A5\B418\BBC0\B85C \BAA8\B4E0 \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \D45C\C2DC\B429\B2C8\B2E4. \C560\D50C\B9AC\CF00\C774\C158\C744 \C775\C2A4\D3EC\D2B8\D558\BA74 \C0AC\C6A9\B41C \C6D0\ACA9 \C11C\BC84\AC00 \C775\C2A4\D3EC\D2B8 \D30C\C77C\C5D0 \CD94\AC00\B429\B2C8\B2E4. \C560\D50C\B9AC\CF00\C774\C158\C744 \B2E4\B978 \C791\C5C5\C601\C5ED\C73C\B85C \C784\D3EC\D2B8\D558\BA74 &PRODUCT_NAME.\C740(\B294) \B3D9\C77C\D55C <strong>\C815\C801 ID</strong>\B97C \C0AC\C6A9\D558\B294 \C6D0\ACA9 \C11C\BC84\AC00 \B300\C0C1 \C791\C5C5\C601\C5ED\C5D0 \C774\BBF8 \D3EC\D568\B418\C5B4 \C788\B294\C9C0 \C5EC\BD80\B97C \D655\C778\D569\B2C8\B2E4. \C6D0\ACA9 \C11C\BC84\AC00 \C874\C7AC\D558\B294 \ACBD\C6B0 \C560\D50C\B9AC\CF00\C774\C158\C740 \AE30\C874 \C6D0\ACA9 \C11C\BC84\B97C \C0AC\C6A9\D569\B2C8\B2E4. \C874\C7AC\D558\C9C0 \C54A\C744 ')
||unistr('\ACBD\C6B0 \C784\D3EC\D2B8 \D30C\C77C\C758 \C6D0\ACA9 \C11C\BC84\AC00 \B300\C0C1 \C791\C5C5\C601\C5ED\C5D0 \C0DD\C131\B429\B2C8\B2E4.</p>')))
