'<ul>',
'    <li><code>base_url</code>:',
unistr('    <em>\B05D\C810 URL</em>\C744 \BCC0\ACBD\D569\B2C8\B2E4.'),
'    </li>',
'    <li><code>substitutions</code>:',
unistr('    <code>apex_t_varchar2</code>\B97C \C0AC\C6A9\D558\C5EC \C774\B984/\AC12 \C30D\C744 \C9C0\C815\D569\B2C8\B2E4.'),
unistr('    &PRODUCT_NAME.\C740(\B294) <em>base url</em> \B610\B294 <em>\B05D\C810 URL</em>\C758 \AC01 <code>#NAME#</code>\C744 \CE58\D658\D569\B2C8\B2E4.'),
'    </li>',
