begin
wwv_flow_imp_page.create_page(
 p_id=>2501.4008
,p_name=>unistr('\D398\C774\C9C0 \C0DD\C131 \B9C8\BC95\C0AC - \D398\C774\C9C0 \C815\C758')
,p_alias=>'CREATE-PAGE-PAGE-DEFINITION'
,p_page_mode=>'MODAL'
,p_step_title=>unistr('\C0DD\C131 &P2500_PAGE_TYPE_DISPLAY.')
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(103848364625132731)
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function showHideButtons()',
'{',
'    // in some cases, we show both CREATE and NEXT buttons on the client side',
'    // depending on options selected, we want to show either of one button ',
'    var lIncludeForm = apex.item("P2501_INCLUDE_FORM").getValue(),',
'        lEditable = apex.item("P2501_EDITABLE").getValue(),',
'        lPageType = apex.item("P2501_PAGE_TYPE").getValue();',
'    // if page type is INTERACTIVE or CLASSIC, logic is simple',
'    // show NEXT button when lIncludeForm is Y, otherwise show CREATE button',
'    if ( lPageType == ''INTERACTIVE'' || lPageType == ''CLASSIC'' )',
'    {',
'        if ( lIncludeForm == ''Y'' )',
'        {',
'            apex.jQuery("button#CREATE").hide();',
'            apex.jQuery("button#NEXT").show();',
'        }',
'        else',
'        {',
'            apex.jQuery("button#CREATE").show();',
'            apex.jQuery("button#NEXT").hide();',
'        }',
'    }',
'    ',
'    // if page type is GRID, then need to consider both lIncludeForm and lEditable values',
'    if ( lPageType == ''GRID'')',
'    {',
'        if ( lIncludeForm == ''Y'' || lEditable == ''Y'' )',
'        {',
'            apex.jQuery("button#CREATE").hide();',
'            apex.jQuery("button#NEXT").show();            ',
'        }',
'        else',
'        {',
'            apex.jQuery("button#CREATE").show();',
'            apex.jQuery("button#NEXT").hide();            ',
'        }',
'    }    ',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// reposition icon picker',
'apex.jQuery("#P2501_PAGE_ICON").after(apex.jQuery("button#icon_picker"));'))
,p_css_file_urls=>'#FONT_APEX_LATEST_DIRECTORY#css/font-apex#MIN#.css'
,p_step_template=>wwv_flow_imp.id(689065306389965836.4008)
,p_page_css_classes=>'a-Dialog--CreatePageDialog'
,p_page_template_options=>'#DEFAULT#'
,p_dialog_attributes=>'minWidth:500,minHeight:400'
,p_protection_level=>'C'
