,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function callItempopUp(s1,s2) {',
'     var items = document.getElementById(s1).value.replace(/\,/g,''~'');',
'     var values = document.getElementById(s2).value.replace(/\,/g,''~'');',
'     var url = ''f?p=&APP_ID.:404:&SESSION.:::404:P404_RETURN1,P404_RETURN2,P404_ITEMS,P404_VALUES:'' + s1 + '','' + s2 + '','' + escape(items) + '','' + escape(values);',
'     popUp (url);',
'}',
'',
'function refreshColumns() {',
'    apex.server.process( ',
'        "getColumnInfo",',
'        { ',
'            pageItems: "#P3120_SEARCH_TYPE,#P3120_LIST_ID,#P3120_LOCATION,#P3120_QUERY_TYPE,#P3120_REMOTE_SOURCE_TYPE,#P3120_ORATEXT_SOURCE_TYPE,#P3120_QUERY_OWNER,#P3120_REMOTE_TABLE_OWNER,#P3120_ORATEXT_OWNER,#P3120_QUERY_TABLE,#P3120_REMOTE_TABLE_'
||'NAME,#P3120_ORATEXT_TABLE,#P3120_QUERY_SQL,#P3120_REMOTE_SQL,#P3120_POST_PROC_TYPE,#P3120_POST_PROC_SQL,#P3120_ORATEXT_SQL,#P3120_QUERY_FUNC_BODY,#P3120_REMOTE_FUNC_BODY,#P3120_POST_PROC_FUNC_BODY,#P3120_QUERY_FUNC_LANG,#P3120_REMOTE_FUNC_BODY_LANG,#'
||'P3120_POST_PROC_FUNC_LANG,#P3120_QUERY_WHERE,#P3120_REMOTE_WHERE,#P3120_POST_PROC_WHERE,#P3120_ORATEXT_WHERE,#P3120_QUERY_ORDER_BY,#P3120_REMOTE_ORDER_BY,#P3120_POST_PROC_ORDER_BY,#P3120_ORATEXT_ORDER_BY,#P3120_OPTIMIZER_HINT,#P3120_REMOTE_SERVER_ID,'
||'#P3120_WEB_SRC_MODULE_ID,#P3120_GRAPH_NAME,#P3120_PQL_MATCH_CLAUSE,#P3120_PQL_COLUMNS_CLAUSE,#P3120_PQL_WHERE_CLAUSE,#P3120_SEARCH_INDEX_NAME,#P3120_SEARCH_SOURCE_NAME,#P3120_SEARCH_ORDER_BY,#P3120_JSON_POST_TYPE,#P3120_JSON_POST_SQL,#P3120_JSON_POST'
||'_FUNC_BODY,#P3120_JSON_POST_FUNC_LANG,#P3120_JSON_POST_WHERE,#P3120_JSON_SOURCE_ID,#P3120_JSON_SRC_ARRAY_COL_ID,#P3120_DV_POST_TYPE,#P3120_DV_POST_SQL,#P3120_DV_POST_FUNC_BODY,#P3120_DV_POST_FUNC_LANG,#P3120_DV_POST_WHERE,#P3120_DUALITY_VIEW_ID,#P312'
||'0_DV_ARRAY_COL_ID,#P3120_VECTOR_SOURCE_TYPE,#P3120_VECTOR_OWNER,#P3120_VECTOR_TABLE,#P3120_VECTOR_SQL,#P3120_VECTOR_WHERE,#P3120_VECTOR_COLUMN" },',
'        {',
'            success: function( pData ) {',
'                var lItems = apex.jQuery( ".is-column");',
'',
'                apex.debug.info( "received column info", pData );',
'',
'                //-----------------------------------------------------------------------------------------',
'                function refreshShuttle( pItemName ) {',
'                    var lItemColumns = apex.item( pItemName ).getValue(),',
'                        lNewColumns  = [];',
'',
'                    if ( lItemColumns && lItemColumns.length > 0 ) {',
'                        for ( let o = 0; o < pData.length; o++ ) {',
'                            if ( pData[ o ].t === "VARCHAR2" || pData[ o ].t === "CLOB" ) {',
'                                lNewColumns.push( pData[ o ].r );',
'                            }',
'                        }',
'                        lItemColumns.filter( function( e ) { return lNewColumns.indexOf( e ) > -1; });',
'                    } else {',
'                        lItemColumns.length = [];',
'                    }',
'        ',
'                    apex.item( pItemName ).setValue( "", undefined, true );',
'                    refreshItem( $( "#" + pItemName + "_LEFT" ), false );',
'                    apex.item( pItemName ).setValue( lItemColumns );',
'                }',
'',
'                //-----------------------------------------------------------------------------------------',
'                function refreshItem( pItem$, pSetValue ) {',
'                    var lValue           = apex.item( pItem$.attr( "name" ) ).getValue(),',
'                        lValueStillValid = false,',
'                        lNullOption$     = pItem$.find( ''option[value=""]''),',
'                        lOption$;',
'',
'                    pItem$.empty();',
'                    if ( lNullOption$.length > 0 ) {',
'                        pItem$.append( lNullOption$ );',
'                    }',
'                    ',
'                    for ( let o = 0; o < pData.length; o++ ) {',
'                        if ( ',
'                            ( pData[ o ].t !== "BLOB" && !pItem$.hasClass("is-blob") && !pItem$.hasClass("is-text") ) ||',
'                            ( pData[ o ].t === "BLOB" &&  pItem$.hasClass("is-blob") && !pItem$.hasClass("is-text") ) || ',
'                            ( ( pData[ o ].t === "BLOB" || pData[ o ].t === "CLOB" || pData[ o ].t === "VARCHAR2" ) && pItem$.hasClass("is-text") ) ',
'                        )',
'                        {',
'                            lOption$ = apex.jQuery("<option></option>").attr("value", pData[ o ].r ).text( pData[ o ].d );',
'                            if ( pData[ o ].r === lValue ) {',
'                                lValueStillValid = true;',
'                            }',
'                            pItem$.append( lOption$ );',
'                        }',
'                    }',
'',
'                    if ( pSetValue ) {',
'                        if ( lValueStillValid ) {',
'                            apex.item( pItem$.attr( "name" ) ).setValue( lValue );',
'                        } else {',
'                            apex.item( pItem$.attr( "name" ) ).setValue( "" );',
'                        }',
'                    }',
'                }',
'',
'                if ( pData.length > 0 ) {',
'',
'                    for (let i=0; i<lItems.length;i++) {',
'                        refreshItem( apex.jQuery (lItems[ i ] ), true );',
'                    }',
'                    if ( apex.jQuery( "#P3120_SEARCHABLE_COLUMNS").length > 0 ) {',
'                        refreshShuttle( "P3120_SEARCHABLE_COLUMNS" );',
'                    }',
'                }',
'            }',
'        }',
'    );',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
