,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    \C77C\BC18 \C0AC\C6A9\C790 \C785\B825\C744 Oracle Text \C9C8\C758\B85C \BCC0\D658\D558\B294 \C0AC\C6A9\C790\C815\C758 PL/SQL \D568\C218\C758 \C774\B984\C744 \C9C0\C815\D569\B2C8\B2E4. '),
unistr('    \C774 \D568\C218\B294 \C77C\BC18 \C0AC\C6A9\C790 \C785\B825\C744 VARCHAR2\B85C \AC00\C838\C640\C11C Oracle Text \C9C8\C758\B97C \ACB0\ACFC\B85C \BC18\D658\D569\B2C8\B2E4.</p>'),
'<p>',
unistr('    \C774 \C608\C81C\C5D0\C11C\B294 <em>Oracle Text \C9C8\C758 \C644\D654</em>\B97C \C0AC\C6A9\D569\B2C8\B2E4. \BA3C\C800 \C815\D655\D55C \C9C8\C758\B97C \C2E4\D589\D55C \B2E4\C74C,'),
unistr('    \C694\CCAD\B41C \D589 \C218\AC00 \BC18\D658\B420 \B54C\AE4C\C9C0 <em>\C720\C0AC \AC80\C0C9</em>\C758 \B808\BCA8\C744 \B298\B824\AC11\B2C8\B2E4.'),
unistr('    \BAA8\B4E0 \C791\C5C5\C740 \C77C\BC18 \C0AC\C6A9\C790\C5D0\AC8C \D22C\BA85\D558\AC8C \C2E4\D589\B429\B2C8\B2E4.'),
'</p>',
'<pre>',
'create or replace function convert_end_user_search (',
'    p_search in varchar2 )',
'    return varchar2 ',
'is',
'    c_xml constant varchar2(32767) := ',
'        ''&lt;query&gt;&lt;textquery>&lt;progression&gt;''          ||',
'          ''&lt;seq&gt;       #SEARCH#            &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,80, 100,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,50,1000,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,20,3000,W) &lt;/seq&gt;'' ||',
'        ''&lt;/progression>&lt;/textquery>&lt;/query&gt;'';',
'',
'    l_search varchar2(32767) := p_search;',
'begin',
'    --',
'    -- remove special characters; ',
'    -- these are irrelevant for full text search',
'    --',
'    l_search := regexp_replace(',
'        srcstr  => l_search, ',
'        pattern => ''[&lt;&gt;{}/()*%&!$?.:,;\+#]'' );',
'',
'    return replace( ',
'        srcstr  => c_xml, ',
'        oldsub  => ''#SEARCH#'', ',
'        newsub  => ''{'' || l_search || ''}'' );',
'end;',
'</pre>',
'<p>',
unistr('    Oracle Text \C9C8\C758 \AD6C\BB38 \BC0F \C9C8\C758 \C644\D654 \AE30\B2A5\C5D0 \B300\D55C \C790\C138\D55C \B0B4\C6A9\C740'),
unistr('    <a rel="noopener noreferrer" target="_blank" href="https://docs.oracle.com/en/database/oracle/oracle-database/23/ccapp/index.html">Oracle Text Application Developers Guide</a>\B97C \CC38\C870\D558\C2ED\C2DC\C624.</p>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
