,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('\AC80\C0C9 \ACB0\ACFC \D589\C744 \D45C\C2DC\D560 HTML \D45C\D604\C2DD\C744 \C785\B825\D569\B2C8\B2E4. <code>&COLUMN.</code> \AD6C\BB38\C744 \C0AC\C6A9\D558\C5EC \C5F4 \AC12\C744 HTML\B85C \D45C\C2DC\D569\B2C8\B2E4. \D15C\D50C\B9AC\D2B8 \C9C0\C2DC\C5B4\B97C \C9C0\C6D0\D569\B2C8\B2E4. \B610\D55C \B2E4\C74C \CE58\D658\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
'</p>',
'<dl>',
'<dt>ICON_TYPE</dt>',
unistr('<dd>\C544\C774\CF58 \C720\D615\C744 \B098\D0C0\B0C5\B2C8\B2E4. <strong>CLASS</strong>, <strong>URL</strong> \B610\B294 <strong>INITIALS</strong>\C77C \C218 \C788\C2B5\B2C8\B2E4.</dd>'),
'<dt>ICON_VALUE</dt>',
unistr('<dd><strong>ICON_TYPE</strong> \AC12\C5D0 \B530\B978 \C2E4\C81C \C544\C774\CF58 \AC12\C785\B2C8\B2E4.</dd>'),
'<dt>RESULT_CSS_CLASSES</dt>',
unistr('<dd><strong>\ACB0\ACFC CSS \D074\B798\C2A4</strong> \C18D\C131\C5D0 \C900\D558\C5EC \AC01 \ACB0\ACFC\C5D0 \C801\C6A9\B41C CSS \D074\B798\C2A4\C785\B2C8\B2E4.</dd>'),
'<dt>APEX$ORATEXT_SCORE</dt>',
unistr('<dd>Oracle Text \AC80\C0C9 \C720\D615\C5D0 \B300\D55C Oracle Text \C810\C218\B97C \B098\D0C0\B0B4\B294 \C5F4\C785\B2C8\B2E4.</dd>'),
'<dt>APEX$VECTOR_DISTANCE</dt>',
unistr('<dd>Oracle Vector Search \AC80\C0C9 \C720\D615\C5D0 \B300\D55C \BCA1\D130 \AC70\B9AC\B97C \B098\D0C0\B0B4\B294 \C5F4\C785\B2C8\B2E4.</dd>'),
'</dl>',
unistr('<p>\C608\C81C:</p>'),
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
