,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Oracle Text \C9C8\C758 \AD6C\BB38\C740 \B9E4\C6B0 \BCF5\C7A1\D558\ACE0 \AC15\B825\D558\BA70 \C640\C77C\B4DC \CE74\B4DC \BB38\C790, \C2A4\D0DC\BC0D, \C720\C0AC \AC80\C0C9 \B4F1\C744 \CC98\B9AC\D560 \C218 \C788\B294 \B2E4\C591\D55C \C9C8\C758 \C5F0\C0B0\C790\B97C \C81C\ACF5\D569\B2C8\B2E4. \C77C\BC18 \C0AC\C6A9\C790\C758 \ACBD\C6B0 \C774 \AD6C\BB38\C744 \C774\D574\D558\AE30 \C5B4\B824\C6B8 \C218\B3C4 \C788\C2B5\B2C8\B2E4. \C0AC\C6A9\C790\C758 \AC80\C0C9 \D504\B85C\C138\C2A4\B97C \AC04\C18C\D654\D558\AE30 \C704\D574 \AC04\B2E8\D55C \C77C\BC18 \C0AC\C6A9\C790 \C785\B825\C744 Oracle Text \C9C8\C758\B85C \C790\B3D9\C73C\B85C \BCC0\D658\D558\B294 \D568\C218\B97C \C120\D0DD\D560 \C218 \C788\C2B5\B2C8\B2E4. \C774\B54C \ACE0\AE09 \AC80\C0C9 \AE30\B2A5\C740 \C790\B3D9\C73C\B85C \C801\C6A9\B429\B2C8\B2E4. \C635\C158\C740 \B2E4\C74C\ACFC \AC19\C2B5\B2C8\B2E4.</p>'),
'<ul>',
unistr('    <li><strong>\C5C6\C74C</strong> - &PRODUCT_NAME.\C740(\B294) <strong>and</strong> \BC0F <strong>or</strong> \D0A4\C6CC\B4DC\B97C \C81C\C678\D55C \AC01 \C9C8\C758\C5B4\B97C "{" \BC0F "}"\B85C \BB36\C2B5\B2C8\B2E4.</li>'),
unistr('    <li><strong>\AC80\C0C9 \C5D4\C9C4</strong> - \C774 \D568\C218\B294 \C9C8\C758 \C644\D654 \AC80\C0C9\C744 \C218\D589\D558\C5EC \C815\D655\D55C \C77C\CE58\B97C \B118\C5B4 \AD00\B828 \ACB0\ACFC\B97C \C77D\C5B4\B4E4\C785\B2C8\B2E4. \BAA9\D45C\B294 \AC00\B2A5\D55C \B9CE\C740 \AD00\B828 \ACB0\ACFC\B97C \C5BB\C5B4\C11C \C0AC\C6A9\C790\AC00 \C815\AD50\D55C \C9C8\C758\B97C \C785\B825\D558\C9C0 \C54A\ACE0\B3C4 \AD00\B828 \C815\BCF4\B97C \C27D\AC8C \CC3E\C744 \C218 \C788\B3C4\B85D \D558\B294 \AC83\C785\B2C8\B2E4. \AC80\C0C9 \D504\B85C\C138\C2A4\B294 \C815\D655\D55C \C77C\CE58 \AC80\C0C9\C73C\B85C \C2DC\C791\D574, \C5B4\AC04 \CD94\CD9C \BC0F \D37C\C9C0 \C77C\CE58\C640 \AC19\C740 \AE30\BC95\C744 \C0AC\C6A9\D558\C5EC \C810\C9C4\C801\C73C\B85C \C9C8\C758\B97C \C644\D654\C2DC\D0B5\B2C8\B2E4. \AC80\C0C9 \C5D4\C9C4 \D568\C218\B294 \ACB0\ACFC \C218\B97C \CD5C\B300\D654\D558\B294 \B3D9\C2DC\C5D0, ')
||unistr('\AC00\C7A5 \C815\D655\D558\ACE0 \AD00\B828\C131 \B192\C740 \C77C\CE58\D56D\BAA9\C774 \D56D\C0C1 \AC80\C0C9 \ACB0\ACFC \C0C1\C704\C5D0 \C624\B974\B3C4\B85D \BCF4\C7A5\D569\B2C8\B2E4.</li>'),
unistr('    <li><strong>\C804\BB38\AC00 \AC80\C0C9</strong> - \C774 \D568\C218\B294 \C815\AD50\D55C \C9C8\C758\B97C \C704\D574 \ACE0\AE09 \AC80\C0C9 \C5F0\C0B0\C790\B97C \C9C0\C6D0\D569\B2C8\B2E4. \C815\D655\D55C \C77C\CE58, \BD80\C6B8 \C5F0\C0B0\C790(AND, OR, NOT), \AD04\D638\B97C \C0AC\C6A9\D55C \C6B0\C120\C21C\C704, \ADFC\C811 \AC80\C0C9\C774 \D5C8\C6A9\B429\B2C8\B2E4. \CD94\AC00 \B9E4\AC1C\BCC0\C218\B97C \C0AC\C6A9\D558\C5EC \AC80\C0C9 \B3D9\C791\C744 \C0AC\C6A9\C790\C815\C758\D560 \C218 \C788\C2B5\B2C8\B2E4. \C774 \BC29\C2DD\C740 \B9E4\C6B0 \AD6C\CCB4\C801\C778 \C9C8\C758\C5D0\C11C \AC00\C7A5 \C815\D655\D55C \ACB0\ACFC\AC00 \D544\C694\D560 \B54C \AC00\C7A5 \C801\D569\D569\B2C8\B2E4. <code>APEX_SEARCH</code> \D328\D0A4\C9C0 \B0B4\C758 <code>QUE')
||unistr('RY_EXPERT_SEARCH</code> \D568\C218\B97C \CC38\C870\D558\C2ED\C2DC\C624.</li>'),
