,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>AI \C11C\BE44\C2A4\C5D0 \B300\D55C \CEE8\D14D\C2A4\D2B8\B85C CSV \CD9C\B825\C744 \C0DD\C131\D558\B294 SQL\C9C8\C758\B97C \C9C0\C815\D569\B2C8\B2E4. \C9C8\C758 \B0B4\C5D0\C11C \B2E4\C74C\ACFC \AC19\C740 \D2B9\C218 \BC14\C778\B4DC \BCC0\C218\B97C \D1B5\D574 \C0AC\C6A9\C790 \D504\B86C\D504\D2B8\C5D0 \C561\C138\C2A4\D558\C5EC \C774\B97C \D3C9\AC00\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
