,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set P3505_SOURCE and P3505_FUNCTION_BODY_LANGUAGE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P3505_SOURCE :=',
'    case :P3505_RAG_TYPE',
'        when ''DATA_SOURCE''   then :P3505_SQL',
'        when ''FUNCTION_BODY'' then',
'            case :P3505_FUNCTION_BODY_LANGUAGE',
'                when ''PLSQL''        then :P3505_FUNCTION_BODY_PLSQL',
'                when ''JAVASCRIPT''   then :P3505_FUNCTION_BODY_JAVASCRIPT',
'            end',
'        when ''STATIC'' then :P3505_STATIC_TEXT',
'    end;',
'',
'-- clear the language if it''s not used',
'if :P3505_RAG_TYPE != ''FUNCTION_BODY'' then',
'    :P3505_FUNCTION_BODY_LANGUAGE := null;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1688845418350941.4008
);
