,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Init Source Fields'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case :P3505_RAG_TYPE',
'    when ''DATA_SOURCE'' then',
'        :P3505_SQL := :P3505_SOURCE;',
'    when ''FUNCTION_BODY'' then',
'        case :P3505_FUNCTION_BODY_LANGUAGE',
'            when ''PLSQL'' then',
'                :P3505_FUNCTION_BODY_PLSQL      := :P3505_SOURCE;',
'            when ''JAVASCRIPT'' then',
'                :P3505_FUNCTION_BODY_JAVASCRIPT := :P3505_SOURCE;',
'        end case;',
'    when ''STATIC'' then',
'        :P3505_STATIC_TEXT := :P3505_SOURCE;',
'end case;'))
