,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('\C560\D50C\B9AC\CF00\C774\C158\C758 \C0AC\C6A9 \AC00\B2A5 \C5EC\BD80\B97C \C9C0\C815\D569\B2C8\B2E4. <p>'),
