unistr('<li><strong>\C0AC\C6A9 \AC00\B2A5</strong> - \C560\D50C\B9AC\CF00\C774\C158\C744 \C81C\D55C \C5C6\C774 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>\AC1C\BC1C\C790 \B3C4\AD6C \BAA8\C74C\C5D0\C11C \C0AC\C6A9 \AC00\B2A5</strong> - \C560\D50C\B9AC\CF00\C774\C158\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \AC1C\BC1C\C790\C758 \ACBD\C6B0 \AC01 \D398\C774\C9C0\C5D0 \AC1C\BC1C\C790 \B3C4\AD6C \BAA8\C74C\C774 \D3EC\D568\B429\B2C8\B2E4. \AC1C\BC1C\C790\AC00 \B3D9\C77C\D55C \BE0C\B77C\C6B0\C800 \C138\C158\C5D0\C11C \C560\D50C\B9AC\CF00\C774\C158 \C791\C131\AE30\C5D0 \B85C\ADF8\C778\D574\C57C \D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\AC1C\BC1C\C790\B9CC \C0AC\C6A9\D560 \C218 \C788\C74C</strong> - \AC1C\BC1C\C790 \AD8C\D55C\C774 \C788\B294 \C0AC\C6A9\C790\B9CC \C560\D50C\B9AC\CF00\C774\C158\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>\C81C\D55C\B41C \C561\C138\C2A4</strong> - \CF64\B9C8\B85C \AD6C\BD84\B41C \C0AC\C6A9\C790 \BAA9\B85D\C73C\B85C \C81C\D55C\B41C \C774\B984\C758 \AC1C\BC1C\C790\B9CC \C560\D50C\B9AC\CF00\C774\C158\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>\C0AC\C6A9 \BD88\AC00</strong> - \C560\D50C\B9AC\CF00\C774\C158\C744 \C2E4\D589\D560 \C218 \C5C6\AC70\B098 \D3B8\C9D1\D560 \C218 \C5C6\C2B5\B2C8\B2E4. \C0AC\C6A9\C790\AC00 \C560\D50C\B9AC\CF00\C774\C158\C5D0 \C561\C138\C2A4\D558\B824\ACE0 \C2DC\B3C4\D558\BA74 [\C0AC\C6A9\D560 \C218 \C5C6\B294 \C560\D50C\B9AC\CF00\C774\C158\C5D0 \B300\D55C \BA54\C2DC\C9C0]\C5D0 \C785\B825\B41C \BA54\C2DC\C9C0\AC00 \D45C\C2DC\B429\B2C8\B2E4.</li>'),
unistr('<li><strong>\C0AC\C6A9 \BD88\AC00(PL/SQL\B85C \D45C\C2DC\B41C \C0C1\D0DC)</strong> - \C560\D50C\B9AC\CF00\C774\C158\C744 \C2E4\D589\D560 \C218 \C5C6\AC70\B098 \D3B8\C9D1\D560 \C218 \C5C6\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>\C0AC\C6A9 \BD88\AC00(URL\B85C \C7AC\C9C0\C815)</strong> - \C560\D50C\B9AC\CF00\C774\C158\C744 \C2E4\D589\D560 \C218 \C5C6\C2B5\B2C8\B2E4. \C0AC\C6A9\C790\B294 [\C0AC\C6A9\D560 \C218 \C5C6\B294 \C560\D50C\B9AC\CF00\C774\C158\C5D0 \B300\D55C \BA54\C2DC\C9C0]\C5D0 \C785\B825\B41C URL\C5D0 \B9C1\D06C\B429\B2C8\B2E4.</li>'),
