wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(206915873780097187.4008)
,p_name=>'P4052_LIST_TEMPLATE_ID'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(53980942183.4008)
,p_prompt=>unistr('\BAA9\B85D \D15C\D50C\B9AC\D2B8')
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P4052_THEME_ID ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P4052_THEME_ID )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P4052_THEME_ID )   as workspace_id',
'      from sys.dual',
')',
'',
'select wwv_flow_escape.html(l.list_template_name)',
'       || decode( ref.ref_count,',
'                  null,',
'                  '''',',
'                  '' ('' || wwv_flow_lang.message( ''APEX.SC.REFERENCES'', ref.ref_count ) || '')''',
'          ) as list_template_name,',
'       l.id',
'  from wwv_flow_list_templates l,',
'       central_theme ct,',
'         ( select count(*) ref_count, list_template_id',
'             from (',
'                    -- Lists in regions',
'                    select list_template_id as list_template_id',
'                      from wwv_flow_page_plugs p',
'                     where p.flow_id = :FB_FLOW_ID',
'                       and p.page_id != 0',
'                       and p.security_group_id = :flow_security_group_id',
'                       and p.list_id           = :F4000_P4052_LIST_ID',
'',
'                    union all',
'                    -- Application Navigation List',
'                    select navigation_list_template_id as list_template_id',
'                      from wwv_flows f',
'                     where f.id = :FB_FLOW_ID',
'                       and f.security_group_id  = :flow_security_group_id',
'                       and f.navigation_list_id = :F4000_P4052_LIST_ID',
'                    ',
'                    union all',
'                    -- Page may have customized navigation list',
'                    select navigation_list_template_id as list_template_id',
'                      from wwv_flow_steps s',
'                     where s.flow_id = :FB_FLOW_ID',
'                       and s.security_group_id  = :flow_security_group_id',
'                       and s.navigation_list_id = :F4000_P4052_LIST_ID',
'',
'                    union all',
'                    -- Navigation Bar List',
'                    select nav_bar_list_template_id as list_template_id',
'                      from wwv_flows f',
'                     where f.id = :FB_FLOW_ID',
'                       and f.security_group_id = :flow_security_group_id',
'                       and f.nav_bar_list_id   = :F4000_P4052_LIST_ID',
'                )',
'            group by list_template_id',
'          ) ref',
'',
' where ( l.flow_id, l.theme_id, l.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P4052_THEME_ID, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and l.id = ref.list_template_id (+)',
'',
'order by ref.ref_count desc nulls last, list_template_name asc;'))
,p_lov_cascade_parent_items=>'P4052_THEME_ID'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('\BCF4\B824\B294 \BAA9\B85D \D15C\D50C\B9AC\D2B8\B97C \C120\D0DD\D569\B2C8\B2E4. \B300\CCB4 \BB38\C790\C5F4 \C18D\C131\C740 \C120\D0DD\D55C \BAA9\B85D \D15C\D50C\B9AC\D2B8\C5D0 \B300\D574 \C790\B3D9\C73C\B85C \D45C\C2DC\B429\B2C8\B2E4. \C18D\C131 \C124\BA85\C740 \AC1C\BC1C\C790\AC00 \BAA9\B85D \D15C\D50C\B9AC\D2B8 \B0B4\C5D0\C11C \C120\D0DD\C801\C778 \B300\CCB4 \BB38\C790\C5F4 #A01# - #A10#\C758 \C6A9\B3C4\B97C \C774\D574\D558\B294 \B370 \B3C4\C6C0\C774 \B429\B2C8\B2E4.')
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
