,p_plug_display_sequence=>30
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>unistr('SQL \C9C8\C758\B97C \AE30\BC18\C73C\B85C \C138 \AC1C \C774\C0C1\C758 \C5F4\C744 \C0AC\C6A9\D558\C5EC \AC12 \BAA9\B85D\C744 \C0DD\C131\D560 \B54C \C5F4\C744 \C9C0\C6D0\D558\B294 \D56D\BAA9(\C608: \D31D\C5C5 LOV)\C5D0 \D574\B2F9 \CD94\AC00 \C5F4\C774 \D45C\C2DC\B418\B3C4\B85D \D558\B824\BA74 LOV\B97C \C0DD\C131\D55C \D6C4 \BA85\C2DC\C801\C73C\B85C \C5F4\C744 \CD94\AC00\D574\C57C \D569\B2C8\B2E4. \D3B8\C9D1 \D398\C774\C9C0\B85C \C774\B3D9\D55C \B2E4\C74C ''\CD94\AC00 \D45C\C2DC \C5F4''\C5D0\C11C \D45C\C2DC\D560 \CD94\AC00 \C5F4\C744 \C120\D0DD\D560 \C218 \C788\B294 ''\C5F4 \C120\D0DD''\C744 \C120\D0DD\D558\BA74 \B429\B2C8\B2E4.')
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_describe_result wwv_flow_exec_dev.t_describe_result;',
'begin',
'    if ( :P4080_LOCATION = ''LOCAL'' and :P4080_SOURCE_TYPE in ( ''SQL'', ''FUNC_BODY_RETURNING_SQL'' )',
'         or ',
'         :P4080_LOCATION = ''REMOTE'' and :P4080_REMOTE_SOURCE_TYPE = ''SQL'' ) ',
'    then ',
'        l_describe_result := wwv_flow_exec_dev.check_and_describe (',
'                                 p_location               => :P4080_LOCATION,',
'                                 p_remote_server_id       => case when :P4080_LOCATION = ''REMOTE'' then :P4080_REMOTE_SERVER_ID end,',
'                                 p_query_type             => :P4080_SOURCE_TYPE,',
'                                 p_sql_query              => case ',
'                                                                 when :P4080_LOCATION = ''LOCAL'' and :P4080_SOURCE_TYPE = ''SQL'' then :P4080_SQL',
'                                                                 when :P4080_LOCATION = ''REMOTE'' and :P4080_REMOTE_SOURCE_TYPE = ''SQL'' then :P4080_REMOTE_SQL',
'                                                             end,',
'                                 p_function_body          => case ',
'                                                                 when :P4080_LOCATION = ''LOCAL'' and :P4080_SOURCE_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P4080_FUNC_BODY',
'                                                             end,',
'                                 p_function_body_language => case ',
'                                                                 when :P4080_LOCATION = ''LOCAL'' and :P4080_SOURCE_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P4080_FUNC_BODY_LANG',
'                                                             end );',
'                                ',
'        return case when l_describe_result.query_columns.count > 2 then true else false end;',
'',
'    end if;',
'end;'))
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
