,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C560\D50C\B9AC\CF00\C774\C158 \D56D\BAA9\C744 \C0AC\C6A9\D558\C5EC \C138\C158 \C0C1\D0DC\B97C \C720\C9C0\BCF4\C218\D569\B2C8\B2E4. \C560\D50C\B9AC\CF00\C774\C158 \D56D\BAA9\C740 \ACC4\C0B0 \B610\B294 \D504\B85C\C138\C2A4\B97C \C0AC\C6A9\D558\AC70\B098 URL\C5D0 \AC12\C744 \C804\B2EC\D558\C5EC \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4. \C138\C158\C5D0 \B300\D574 \D55C \BC88 \D56D\BAA9 \AC12\C744 \C124\C815\D558\B824\BA74 "\C0C8 \C778\C2A4\D134\C2A4 \C2DC\C791 \C2DC" \ACC4\C0B0\C744 \C0AC\C6A9\D569\B2C8\B2E4. \D45C\C2DC\B418\C9C0 \C54A\ACE0 \C784\C758\C758 \D55C \D398\C774\C9C0\C5D0 \D55C\C815\B418\C9C0 \C54A\C740 \C138\C158 \C0C1\D0DC\B97C \C720\C9C0\BCF4\C218\D558\B824\BA74 \C560\D50C\B9AC\CF00\C774\C158 \D56D\BAA9\C744 \C0AC\C6A9\D569\B2C8\B2E4.</p>'),
