,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4008)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\AC12 \BAA9\B85D\C740 \D398\C774\C9C0 \D56D\BAA9\BFD0\B9CC \C544\B2C8\B77C \BCF4\ACE0\C11C \D544\B4DC\B85C \CC38\C870\B420 \C218 \C788\C2B5\B2C8\B2E4. \AC12 \BAA9\B85D\C740 \D45C\C2DC\B418\B294 \AC12\C744 \C81C\C5B4\D558\ACE0 \C0AC\C6A9\C790\C758 \C120\D0DD\C0AC\D56D\C744 \C81C\D55C\D569\B2C8\B2E4. \AC12 \BAA9\B85D\C740 \C815\C801(\C0AC\C6A9\C790\AC00 \C785\B825\D558\B294 \AC12\C5D0 \AE30\BC18\D568) \B610\B294 \B3D9\C801(\B85C\CEEC \B370\C774\D130\BCA0\C774\C2A4, REST \C0AC\C6A9 SQL \B610\B294 REST \B370\C774\D130 \C18C\C2A4\C758 \C5EC\B7EC \B370\C774\D130 \C18C\C2A4\C5D0 \AE30\BC18\D568)\C77C \C218 \C788\C2B5\B2C8\B2E4.</p>'),
