'        ''P4111_DISPLAY_COLUMN'':      apex.item( ''P4111_DISPLAY_COLUMN'' ).getValue(),',
'        ''P4111_GROUP_COLUMN'':        apex.item( ''P4111_GROUP_COLUMN'' ).getValue(),',
'        ''P4111_ICON_COLUMN'':         apex.item( ''P4111_ICON_COLUMN'' ).getValue(),',
'        ''P4111_DEFAULT_SORT_COLUMN'': apex.item( ''P4111_DEFAULT_SORT_COLUMN'' ).getValue(),',
'        ''P4111_ORACLE_TEXT_COLUMN'':  apex.item( ''P4111_ORACLE_TEXT_COLUMN'' ).getValue(),        ',
'    };',
'}',
'',
'// Set column mapping value',
'function setColumnMappings( pItemName ){',
'    var lValue = p4111.columnMappingValues[ pItemName ];',
'    if ( lValue ) {',
'        apex.item( pItemName ).setValue( lValue );',
'    }',
'}',
'',
'// Checks if the current source definition is a valid one (has everything defined that needs to be, to get column information).',
'function isValidSourceDefinition(){ ',
'    var lLocation           = apex.item( ''P4111_LOCATION'' ),',
'        lSourceType         = apex.item( ''P4111_SOURCE_TYPE'' ),',
'        lLovQuerySQL        = apex.item( ''P4111_LOV_QUERY_SQL'' ),',
'        lLovQueryFunc       = apex.item( ''P4111_LOV_QUERY_FUNC_BODY'' ),',
'        lQueryTable         = apex.item( ''P4111_QUERY_TABLE'' ),',
'        lRemoteSourceType   = apex.item( ''P4111_REMOTE_SOURCE_TYPE'' ),',
'        lRemoteSQL          = apex.item( ''P4111_REMOTE_SQL'' ),',
'        lRemoteTableName    = apex.item( ''P4111_REMOTE_TABLE_NAME'' ),',
'        lWebSrcModule       = apex.item( ''P4111_WEB_SRC_MODULE_ID'' ),',
'        lDualityView        = apex.item( ''P4111_DUALITY_VIEW_ID'' ),',
'        lJsonSource         = apex.item( ''P4111_JSON_SOURCE_ID'' ),',
'        lGraphName          = apex.item( ''P4111_GRAPH_NAME'' ),',
'        lMatchClause        = apex.item( ''P4111_PQL_MATCH_CLAUSE'' ),',
'        lColumnsClause      = apex.item( ''P4111_PQL_COLUMNS_CLAUSE'' );',
'    ',
'    switch ( lLocation.getValue() ) {',
'        case ''LOCAL'':      ',
'            switch ( lSourceType.getValue() ) {',
'                case ''SQL'':',
'                    return !lLovQuerySQL.isEmpty();',
'                    break;',
'                case ''FUNC_BODY_RETURNING_SQL'':',
'                    return !lLovQueryFunc.isEmpty();',
'                    break;',
'                case ''TABLE'':',
'                    return !lQueryTable.isEmpty();',
'                case ''GRAPH'':',
'                    return !lGraphName.isEmpty() && !lMatchClause.isEmpty() && !lColumnsClause.isEmpty();',
'            };',
'            break;',
'        case ''REMOTE'':',
'            switch ( lRemoteSourceType.getValue() ) {',
'                case ''SQL'':',
'                    return !lRemoteSQL.isEmpty();',
'                    break;',
'                case ''TABLE'':',
'                    return !lRemoteTableName.isEmpty();',
'            };',
'            break;',
'        case ''WEB_SOURCE'':',
'                return !lWebSrcModule.isEmpty();',
'        case ''DUALITY_VIEW'':',
'                return !lDualityView.isEmpty();',
'        case ''JSON_COLLECTION'':',
'                return !lJsonSource.isEmpty();',
'    }',
'    ',
'    return false;',
'}',
''))
,p_step_template=>wwv_flow_imp.id(689605897838965863.4008)
,p_page_template_options=>'#DEFAULT#'
,p_read_only_when_type=>'EXPRESSION'
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'( :F4000_P4111_ID is not null  ',
'  and wwv_flow_lov_dev.is_based_on_graph( :F4000_P4111_ID ) ',
'  and sys.dbms_db_version.version < 23 ) ',
'or :F4000_P4111_REFERENCE_ID is not null'))
,p_read_only_when2=>'PLSQL'
,p_help_text=>'bldapp_lov.htm'
);
