'<pre>',
'SELECT ename d, empno r',
'FROM  emp ',
'WHERE deptno = :my_item ',
'ORDER BY 1',
'</pre>',
unistr('\C608\C81C 2(\C9C8\C758\C5D0 \C778\B77C\C778 \C9C8\C758 \D3EC\D568, SQL \BB38\C758 \CCAB\BC88\C9F8 FROM \C808\C774 \C778\B77C\C778 \C9C8\C758\C5D0 \C18D\D558\C9C0 \C54A\C544\C57C \D568):'),
