,p_prompt=>unistr('\C138\C158 \C0C1\D0DC \BCF4\D638')
,p_source=>'PROTECTION_LEVEL'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ITEM PROTECTION LEVEL D'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select nvl(PAGE_PROTECTION_ENABLED_Y_N,''N'') p from wwv_flows where id = :FB_FLOW_ID) loop',
'    if c1.p = ''Y'' then',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_APPLICATION'''') d, ''''B'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_USER'''') d, ''''P'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_SESSION'''') d, ''''S'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    else',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    end if;',
'end loop;'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('\C774 \D56D\BAA9\C5D0 \B300\D55C \C138\C158 \C0C1\D0DC \BCF4\D638\B97C \C120\D0DD\D558\C2ED\C2DC\C624.'),
'<ul>',
unistr('<li><strong>\C81C\D55C \C5C6\C74C</strong> - URL \B610\B294 \D3FC\C5D0\C11C \D56D\BAA9 \C774\B984/\AC12\C744 \C804\B2EC\D558\C5EC \D56D\BAA9\C744 \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4. URL\C5D0\B294 \CCB4\D06C\C12C\C774 \D544\C694\D558\C9C0 \C54A\C2B5\B2C8\B2E4.</li><br />       '),
unistr('<li><strong>\C81C\D55C\B428 - \BE0C\B77C\C6B0\C800\C5D0\C11C \C124\C815\D560 \C218 \C5C6\C74C</strong> - URL \B610\B294 POSTDATA\B97C \D1B5\D574 \D56D\BAA9\C744 \BCC0\ACBD\D560 \C218 \C5C6\C2B5\B2C8\B2E4. \D56D\BAA9 \AC12\C744 \B0B4\BD80 \D504\B85C\C138\C2A4, \ACC4\C0B0 \B4F1\C73C\B85C \C124\C815\D560 \C218 \C788\B294 \BC29\BC95\C744 \C81C\D55C\D558\B824\ACE0 \D560 \B54C \C774 \C18D\C131\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624. \B370\C774\D130 \C785\B825 \D56D\BAA9\C73C\B85C \C0AC\C6A9\D560 \C218 \C5C6\B294 \D56D\BAA9\C5D0\B9CC \C801\C6A9\B418\B294 \C774 \C18D\C131\C740 \C138\C158 \C0C1\D0DC \BCF4\C548 \AE30\B2A5\C774 \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\B418\C5B4 \C788\B354\B77C\B3C4 \D56D\C0C1 \AD00\CC30\B429\B2C8\B2E4. \B2E4\C74C "\D45C\C2DC \D615\C2DD" \C720\D615 \C911 \D558\B098\AC00 \C788\B294 \D398\C774\C9C0 \D56D\BAA9 \B610\B294')
||unistr(' \C560\D50C\B9AC\CF00\C774\C158 \D56D\BAA9\C5D0 \C774 \C18D\C131\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
'<br />',
'<ul>',
unistr('<li>\D45C\C2DC \C804\C6A9(\C800\C7A5 \C0C1\D0DC=No)</li>'),
unistr('<li>\D14D\C2A4\D2B8 \D544\B4DC(\C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\B428, \C0C1\D0DC\B97C \C800\C7A5\D558\C9C0 \C54A\C74C)</li>                          '),
unistr('<li>\ADF8\B9AC\B4DC \B808\C774\C544\C6C3 \C815\C9C0 \BC0F \C2DC\C791(\B808\C774\BE14\B9CC \D45C\C2DC)</li>'),
'</li></ul>',
unistr('<li><strong>\CCB4\D06C\C12C \D544\C694: \C560\D50C\B9AC\CF00\C774\C158 \B808\BCA8</strong> - \D2B9\C815 \C791\C5C5\C601\C5ED \BC0F \C560\D50C\B9AC\CF00\C774\C158\C5D0 \D574\B2F9\B418\B294 \CCB4\D06C\C12C\B3C4 \C81C\ACF5\B418\B294 \ACBD\C6B0 URL\C5D0\C11C \D56D\BAA9 \C774\B984/\AC12\C744 \C804\B2EC\D558\C5EC \D56D\BAA9\C744 \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4. \B2E4\B978 \C138\C158\C5D0 \C788\C9C0\B9CC \D604\C7AC \C791\C5C5\C601\C5ED\C5D0\C11C \B3D9\C77C\D55C \C560\D50C\B9AC\CF00\C774\C158\C744 \C2E4\D589 \C911\C778 \C0AC\C6A9\C790\C5D0 \C758\D574 \C0DD\C131\B41C \CCB4\D06C\C12C\C774 \C788\B294 URL\C744 \D1B5\D574\C11C\B9CC \D56D\BAA9\C744 \C124\C815\D558\B3C4\B85D \D5C8\C6A9\D558\B824\ACE0 \D560 \B54C \C774 \C635\C158\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624.</li>'),
