'',
unistr('<p>\C5EC\AE30\C5D0 \C785\B825\D558\B294 \D30C\C77C URL\C740 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\C5D0\C11C <code>#TEMPLATE_CSS#</code> \B300\CCB4 \BB38\C790\C5F4\C744 \BC14\AFC9\B2C8\B2E4.</p>'),
