,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\AC1C\BC1C\C790\AC00 \C9C0\C815\D55C \C0AC\C6A9\C790\C815\C758 \C18D\C131\AC12\C5D0 \B300\CCB4 \AD6C\BB38(\C608: <code>&amp;P1_DNAME.</code>)\C73C\B85C \CC38\C870\B41C \D56D\BAA9\C774 \D3EC\D568\B418\C5B4 \C788\C744 \C218 \C788\C2B5\B2C8\B2E4.'),
'</p>',
unistr('<p>\C18D\C131\AC12 \B300\CCB4\AC00 <strong>\C124\C815</strong>\C73C\B85C \C124\C815\B418\BA74 \D50C\B7EC\ADF8\C778\C744 \D638\CD9C\D558\AE30 \C804\C5D0 &PRODUCT_NAME.\C5D0\C11C \C790\B3D9\C73C\B85C \C774\B7EC\D55C \CC38\C870\B97C \C2E4\C81C \AC12\C73C\B85C \BC14\AFC9\B2C8\B2E4.'),
'</p>',
unistr('<p>\C18D\C131\AC12 \B300\CCB4\AC00 <strong>\D574\C81C</strong>\B85C \C124\C815\B418\BA74 \AC12\C774 <code>p_plugin, p_item, p_region, ...</code>\C758 <code>attribute_01 - attribute_25</code> \B808\CF54\B4DC \C720\D615 \C18D\C131\C5D0 \BCC0\ACBD\B418\C9C0 \C54A\C740 \C0C1\D0DC\B85C \AE30\B85D\B418\BA70, \D50C\B7EC\ADF8\C778 \AC1C\BC1C\C790\AC00 \C774\B7EC\D55C \B300\CCB4 \AD6C\BB38 \CC38\C870\B97C <code>apex_plugin_util.replace_substitutions</code>\C5D0 \B300\D55C \D638\CD9C\B85C \BC14\AFB8\AC70\B098 \C774\C640 \C720\C0AC')
||unistr('\D55C \B300\CCB4\B97C \C218\D589\D569\B2C8\B2E4.'),
'</p>',
unistr('<p>\C0AC\C6A9\C790\C815\C758 \D50C\B7EC\ADF8\C778 \C18D\C131\C774 \D15C\D50C\B9AC\D2B8\B85C \C0AC\C6A9\B418\ACE0 \B300\CCB4 \AD6C\BB38\C774 \D50C\B7EC\ADF8\C778\C744 \D1B5\D574 \C2E4\D589\B41C SQL \BB38\C758 \D398\C774\C9C0 \D56D\BAA9 \BC0F \C5F4\C744 \CC38\C870\D558\B294 \B370 \C0AC\C6A9\B418\B294 \ACBD\C6B0 <strong>\D574\C81C</strong>\B85C \C124\C815\D569\B2C8\B2E4. SQL \BB38\C758 \C5F4 \AC12\C740 \D50C\B7EC\ADF8\C778\C774 \D638\CD9C\B420 \B54C \C0AC\C6A9\D560 \C218 \C5C6\C73C\BBC0\B85C \D50C\B7EC\ADF8\C778 \C790\CCB4\C5D0\C11C \BC14\AFB8\AE30\B97C \C218\D589\D574\C57C \D569\B2C8\B2E4.'),
'</p>',
unistr('<p>\AC01 \D589\C5D0 \B300\D574 \C5F4 \AC12\C744 \C218\B3D9\C73C\B85C \B300\CCB4\D558\AE30 \C704\D55C \C608:</p>'),
'<pre>',
'/* Read data */',
'l_column_value_list := apex_plugin_util.get_data2 (',
'                           p_sql_statement => p_region.source,',
'                           p_region        => p_region );',
'/* Emit rows */',
'for l_row_num in 1 .. l_column_value_list( 1 ).value_list.count loop',
'    begin',
'        -- Assign the column values of the current row',
'        -- into session state',
'        apex_plugin_util.set_component_values (',
'            p_column_value_list => l_column_value_list,',
'            p_row_num           => l_row_num );',
'',
'        ...',
'',
'        -- Link Attribute: Replace substitution variables',
'        -- (including column values of the current row)',
'        l_link := apex_plugin_util.replace_substitutions(',
'                      p_value => p_region.attribute_01 );',
'        ...',
'',
'        apex_plugin_util.clear_component_values;',
'    exception when others then',
'        apex_plugin_util.clear_component_values;',
'        raise;',
'    end;',
'end loop;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
