wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(1910723550989902.4008)
,p_event_id=>wwv_flow_imp.id(1910627027989901.4008)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let item = apex.item( "P4410_TMPL_COMPONENT_TYPES" );',
'let value = item.getValue();',
'if ( value.includes( "REGION_ONLY") ) {',
'    $( "input[value=PARTIAL],input[value=REPORT]", item.element ).prop( {',
'        "disabled": true,',
'        "checked": false',
'    } );',
'} else if ( value.includes( "REPORT" ) || value.includes( "PARTIAL" ) ) {',
'    $( "input[value=REGION_ONLY]", item.element ).prop( {',
'        "disabled": true,',
'        "checked": false',
'    } );',
'} else {',
'    $( "input[value=REGION_ONLY],input[value=REPORT],input[value=PARTIAL]", item.element ).prop( {',
'        "disabled": false',
'    } );',
'}'))
);
