,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C778\C99D \B2E8\ACC4(\B85C\ADF8\C778 \C778\C99D\C11C \D655\C778) \C774\D6C4 &PRODUCT_NAME. \B85C\ADF8\C778 \D504\B85C\C2DC\C800(\B85C\ADF8\C778 API)\AC00'),
unistr('\C2E4\D589\D560 \D504\B85C\C2DC\C800\C758 \C774\B984\C744 \C9C0\C815\D569\B2C8\B2E4. \B85C\ADF8\C778 \D504\B85C\C2DC\C800\B294 \C0AC\C6A9\C790 \C778\C99D\C11C\B97C \D655\C778\D55C \D6C4, \C0AC\C6A9\C790\B97C'),
unistr('\C138\C158\C5D0 \B4F1\B85D\D558\ACE0 \C6D0\D558\B294 \C560\D50C\B9AC\CF00\C774\C158 \D398\C774\C9C0\B85C \C7AC\C9C0\C815\D558\AE30 \C804\C5D0 \C774 \CF54\B4DC\B97C \C2E4\D589\D569\B2C8\B2E4.'),
unistr('\C774 \D504\B85C\C2DC\C800\B294 PL/SQL \CF54\B4DC \C18D\C131\C5D0\C11C \C815\C758\D558\AC70\B098 \B370\C774\D130\BCA0\C774\C2A4 \B0B4\C5D0\C11C \C815\C758\D560 \C218'),
unistr('\C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p>\C608\B97C \B4E4\C5B4, <code>JOHNDOE@EXAMPLE.COM</code> \C778\C99D \C0AC\C6A9\C790 \C774\B984\C744'),
unistr('<code>JOHNDOE</code>\B85C \BCC0\D658\D558\B824\BA74 PL/SQL \CF54\B4DC \C18D\C131\C5D0\C11C <code>my_post_auth</code> \D504\B85C\C2DC\C800\B97C \C815\C758\D569\B2C8\B2E4.</p>'),
'<pre>',
'procedure my_post_auth',
'is',
