unistr('<p>\C774 \D398\C774\C9C0\C5D0 \B85C\B4DC\D560 \CF54\B4DC\C5D0 \B300\D574 JavaScript \D30C\C77C URL\C744 \C785\B825\D558\C2ED\C2DC\C624. \AC01 URL\C740 \C0C8 \D589\C5D0 \C791\C131\D574\C57C \D569\B2C8\B2E4. \D30C\C77C\C758 \CD5C\C18C\D654\B41C \BC84\C804\C744 \C81C\ACF5\D560 \ACBD\C6B0, \C77C\BC18 \D398\C774\C9C0 \BCF4\AE30\B97C \C704\D574\C11C\B294 \D30C\C77C URL\C5D0 <code>.min</code>\C744 \D3EC\D568\D558\B3C4\B85D \B300\CCB4 \BB38\C790\C5F4 <code>#MIN#</code>\C744 \C0AC\C6A9\D558\AC70\B098 <code>minified/</code>\B97C \D3EC\D568\D558\B3C4\B85D <code>#MIN_DIRECTORY#</code>\B97C \C0AC\C6A9\D560 \C218 \C788\C73C\BA70, \D398\C774\C9C0\B97C \B514')
||unistr('\BC84\ADF8 \BAA8\B4DC\B85C \D45C\C2DC\D560 \B54C\B294 \BE48 \BB38\C790\C5F4\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \B610\D55C \C560\D50C\B9AC\CF00\C774\C158\C758 \BC84\C804\C744 \D30C\C77C URL\C5D0 \D3EC\D568\D558\B824\B294 \ACBD\C6B0 \B300\CCB4 \BB38\C790\C5F4 <code>#APP_VERSION#</code>\C5D0 \C561\C138\C2A4\D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p>\CC38\ACE0: \C5F4\AE30 \B610\B294 \B2EB\AE30 <code>script</code> \D0DC\ADF8\B294 \D3EC\D568\D558\C9C0 \C54A\C544\B3C4 \B429\B2C8\B2E4. URL\B9CC \C791\C131\D558\C2ED\C2DC\C624.'),
