'      <pre>/myjs/#MIN_DIRECTORY#main#MIN#.js</pre>',
'  </li>',
unistr('  <li>\B77C\C774\BE0C\B7EC\B9AC\AC00 RequireJS \D544\C218 \D638\CD9C\C5D0\C11C\B3C4 \C0AC\C6A9\B418\B294 \ACBD\C6B0 \C774 \AD6C\BB38\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624. \C815\C758 \C774\B984\C740 requirejs.config \ACBD\B85C\C5D0\C11C \C0AC\C6A9\B418\B294 \AC83\ACFC \C77C\CE58\D574\C57C \D558\ACE0 \AC12\C740 \B77C\C774\BE0C\B7EC\B9AC\AC00 \BCF4\C5EC\C8FC\B294 \C804\C5ED \AE30\D638\C5EC\C57C \D569\B2C8\B2E4. RequireJS\B97C \C0AC\C6A9\D558\B294 \ACBD\C6B0\C5D0\B9CC \C801\C6A9\B429\B2C8\B2E4. \C774\B294 RequireJS\AC00 \B77C\C774\BE0C\B7EC\B9AC\B97C \B450 \BC88 \B85C\B4DC\D558\B294 \AC83\C744 \BC29\C9C0\D569\B2C8\B2E4.'),
'      <pre>[define hammerjs=Hammer]/myjs/hammer.js</pre>',
'  </li>',
unistr('  <li>\D30C\C77C\C5D0 RequireJS\C758 \C885\C18D\C131\C774 \C788\B294 \ACBD\C6B0 \C774 \AD6C\BB38\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624. \C774 \D30C\C77C \C804\C5D0 RequireJS\B97C \C790\B3D9\C73C\B85C \B85C\B4DC\D569\B2C8\B2E4.'),
