unistr('  <li>\D30C\C77C\C5D0 Oracle JET\C758 \C885\C18D\C131\C774 \C788\B294 \ACBD\C6B0 \C774 \AD6C\BB38\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624. \C774 \D30C\C77C \C804\C5D0 RequireJS\C640 Oracle JET RequireJS \AD6C\C131\C744 \C790\B3D9\C73C\B85C \B85C\B4DC\D569\B2C8\B2E4.'),
