wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(3615672659145066.4008)
,p_validation_name=>'unique template name'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P4654_THEME_ID ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P4654_THEME_ID )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P4654_THEME_ID )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_row_templates rt,',
'       central_theme ct',
' where ( rt.flow_id, rt.theme_id, rt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P4654_THEME_ID, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and rt.row_template_name = :F4000_P4654_ROW_TEMPLATE_NAME',
'   and rt.id               != :F4000_P4654_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('\D15C\D50C\B9AC\D2B8 \C774\B984\C740 \ACE0\C720\D574\C57C \D569\B2C8\B2E4.')
