,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">\C774\C804 \C775\C2A4\D3EC\D2B8\B85C \B418\B3CC\C544\AC08 \C2DC\AC04(\BD84)\C744 \C9C0\C815\D569\B2C8\B2E4. \C774 \C635\C158\C744 \C0AC\C6A9\D558\BA74 \C560\D50C\B9AC\CF00\C774\C158\C758 \D2B9\C815 \C791\C5C5 \C2DC\AC04\C73C\B85C \B418\B3CC\C544\AC00\C11C \C0AD\C81C\B41C \AC1D\CCB4\B97C \BCF5\C6D0\D560 \C218 \C788\C2B5\B2C8\B2E4.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">\C774 \C720\D2F8\B9AC\D2F0\B294 <code>dbms_flashback</code> \D328\D0A4\C9C0\B97C \C0AC\C6A9\D569\B2C8\B2E4. SCN(\C2DC\C2A4\D15C \BCC0\ACBD \BC88\D638) \B9E4\D551\C5D0 \B300\D55C \C2DC\AC04\AE30\B85D\C740 \C57D 5\BD84\B9C8\B2E4 \C0C8\B85C\ACE0\CE68\B418\BBC0\B85C \D604\C7AC\C5D0\C11C 5\BD84 \C804\C758 \BC84\C804\C73C\B85C \B418\B3CC\C544\AC08 \C218 \C788\C2B5\B2C8\B2E4. \C2E4\D589 \CDE8\C18C \C815\BCF4\AC00 \BCF4\C874\B418\B294 \C2DC\AC04\C740 \C2DC\C791 \B9E4\AC1C\BCC0\C218 <code>undo_retention</code>(\AE30\BCF8\AC12 3\C2DC\AC04)\C5D0 \B530\B77C \C801\C6A9\B418\C9C0\B9CC \C2E4\D589 \CDE8\C18C \D14C\C774\BE14\C2A4\D398\C774\C2A4\C758 \D06C\AE30\C5D0\B9CC \C601\D5A5\C744 \C90D\B2C8\B2E4')
||'.</div>',
unistr('<div class="htmldbInfoBodyP">\B450 \AC1C\C758 \B370\C774\D130\BCA0\C774\C2A4\C5D0 \B3D9\C77C\D55C <code>undo_retention</code> \B9E4\AC1C\BCC0\C218\AC00 \C788\B294 \ACBD\C6B0, \C774\C804 \B370\C774\D130\AC00 \C544\CE74\C774\BE0C\B418\B3C4\B85D \D2B8\B79C\C7AD\C158\C774 \C2E4\D589 \CDE8\C18C \D14C\C774\BE14\C2A4\D398\C774\C2A4\C5D0 \CC44\C6CC\C9C0\C9C0 \C54A\C73C\BBC0\B85C \D2B8\B79C\C7AD\C158\C774 \C801\C740, \D6E8\C52C \C774\C804 \C2DC\C810\C758 \B370\C774\D130\BCA0\C774\C2A4\B85C \B418\B3CC\C544\AC08 \C218 \C788\C2B5\B2C8\B2E4.</div>')))
