'declare',
'    procedure clear_json is',
'    begin',
'        :P7021_SOURCE_POST_PROCESSING := null;',
'        :P7021_WEB_SRC_MODULE_ID      := null;',
'        :P7021_DOCUMENT_SOURCE_ID     := null;',
'        :P7021_WEB_SRC_ARRAY_COL_ID   := null;',
'    end clear_json;',
'',
'    procedure clear_table is',
'    begin',
'        :P7021_TABLE_NAME             := null;',
'        :P7021_TABLE_OWNER            := null;',
'        :P7021_QUERY_WHERE            := null;',
'        :P7021_QUERY_ORDER_BY         := null;',
'        :P7021_PQL_COLUMNS_CLAUSE     := null;',
'        :P7021_PQL_MATCH_CLAUSE       := null;',
'        :P7021_OPTIMIZER_HINT         := null;',
'        :P7021_INCLUDE_ROWID_COLUMN   := ''N'';',
'    end clear_table;',
'',
'begin',
'    if :P7021_SOURCE_TYPE = ''QUERY'' then',
'',
'        :P7021_TABLE_RESULT_TYPE := :P7021_RESULT_TYPE;',
'',
'        if :P7021_LOCATION = ''REMOTE'' then',
'',
'            :P7021_REMOTE_DATA_SOURCE_TYPE := coalesce( :P7021_REMOTE_DATA_SOURCE_TYPE, ''TABLE'' );',
'            --',
'            :P7021_TABLE_OWNER             := :P7021_REMOTE_TABLE_OWNER;',
'            :P7021_TABLE_NAME              := :P7021_REMOTE_TABLE_NAME;',
'            :P7021_LOCAL_DATA_SOURCE_TYPE  := :P7021_REMOTE_DATA_SOURCE_TYPE;',
'            :P7021_SQL                     := case :P7021_REMOTE_DATA_SOURCE_TYPE',
'                                                  when ''SQL''                     then :P7021_REMOTE_SQL',
'                                                  when ''FUNC_BODY_RETURNING_SQL'' then :P7021_REMOTE_FUNC_BODY end;',
'            :P7021_FUNCTION_BODY_LANGUAGE  := case when :P7021_REMOTE_DATA_SOURCE_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P7021_REMOTE_FUNC_BODY_LANG end;',
'            :P7021_INCLUDE_ROWID_COLUMN    := case when :P7021_REMOTE_DATA_SOURCE_TYPE = ''TABLE'' then :P7021_REMOTE_INCLUDE_ROWID else ''N'' end;',
'            :P7021_QUERY_WHERE             := :P7021_REMOTE_WHERE;',
'            :P7021_QUERY_ORDER_BY          := :P7021_REMOTE_ORDER_BY;',
'            clear_json;',
'',
'        elsif :P7021_LOCATION = ''LOCAL'' then',
'',
'            :P7021_REMOTE_SERVER_ID       := null;',
'            :P7021_LOCAL_DATA_SOURCE_TYPE := coalesce( :P7021_LOCAL_DATA_SOURCE_TYPE, ''TABLE'' );',
'            :P7021_SQL                    := case :P7021_LOCAL_DATA_SOURCE_TYPE',
'                                                 when ''SQL''                     then :P7021_SQL',
'                                                 when ''FUNC_BODY_RETURNING_SQL'' then :P7021_FUNCTION_BODY end;',
'            :P7021_FUNCTION_BODY_LANGUAGE := case when :P7021_LOCAL_DATA_SOURCE_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P7021_FUNCTION_BODY_LANGUAGE end;',
'            :P7021_INCLUDE_ROWID_COLUMN   := case when :P7021_LOCAL_DATA_SOURCE_TYPE = ''TABLE'' then :P7021_INCLUDE_ROWID_COLUMN else ''N'' end;',
'            if :P7021_LOCAL_DATA_SOURCE_TYPE = ''GRAPH'' then',
'                :P7021_TABLE_NAME := :P7021_GRAPH_NAME;',
'                :P7021_QUERY_WHERE := :P7021_PQL_WHERE_CLAUSE;',
'            end if;',
'            clear_json;',
'',
'        elsif :P7021_LOCATION = ''WEB_SOURCE'' then',
'            if     :P7021_OLD_WEB_SRC_MODULE_ID                     = :P7021_WEB_SRC_MODULE_ID',
'               and coalesce( :P7021_OLD_WEB_SRC_ARRAY_COL_ID, ''X'' ) = coalesce( :P7021_WEB_SRC_ARRAY_COL_ID, ''X'' )',
'            then',
'                if :P7021_SOURCE_POST_PROCESSING = ''WHERE_ORDER_BY_CLAUSE'' then',
'                    :P7021_QUERY_WHERE            := :P7021_POST_PROCESS_WHERE;',
'                    :P7021_QUERY_ORDER_BY         := :P7021_POST_PROCESS_ORDERBY;',
'                    :P7021_FUNCTION_BODY_LANGUAGE := null;',
'                elsif :P7021_SOURCE_POST_PROCESSING = ''SQL'' then',
'                    :P7021_SQL                    := :P7021_POST_PROCESS_QUERY;',
'                    :P7021_FUNCTION_BODY_LANGUAGE := null;',
'                elsif :P7021_SOURCE_POST_PROCESSING = ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P7021_SQL                    := :P7021_POST_PROC_FUNC_BODY;',
'                    :P7021_FUNCTION_BODY_LANGUAGE := :P7021_POST_PROC_FUNC_BODY_LANG;',
'                end if;',
'            else',
'                 :P7021_SOURCE_POST_PROCESSING := null;',
'                 :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            end if;',
'            :P7021_REMOTE_SERVER_ID           := null;',
'            :P7021_DOCUMENT_SOURCE_ID         := null;',
'            :P7021_INCLUDE_ROWID_COLUMN       := ''N'';',
'            :P7021_SOURCE_POST_PROCESSING     := nullif ( :P7021_SOURCE_POST_PROCESSING, ''NONE'' );',
'            :P7021_TABLE_USELOCALSYNCTABLE    := case',
'                                                 when wwv_flow_web_src_sync.sync_exists_for_array_column(',
'                                                          p_web_source_module_id => :P7021_WEB_SRC_MODULE_ID,',
'                                                          p_array_column_id      => :P7021_WEB_SRC_ARRAY_COL_ID ) = ''Y''',
'                                                 then coalesce(:P7021_USE_LOCAL_SYNC_TABLE,''N'')',
'                                                 end;',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_duality_view then',
'',
'            :P7021_WEB_SRC_ARRAY_COL_ID := :P7021_DVSRC_ARRAYCOL_ID;',
'            :P7021_DOCUMENT_SOURCE_ID   := :P7021_DUALITY_VIEW_ID;',
'',
'            if :P7021_DVPOST = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P7021_QUERY_WHERE            := :P7021_DVPOST_WHERE;',
'                :P7021_QUERY_ORDER_BY         := :P7021_DVPOST_ORDERBY;',
'                :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            elsif :P7021_DVPOST = ''SQL'' then',
'                :P7021_SQL                    := :P7021_DVPOST_QUERY;',
'                :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            elsif :P7021_DVPOST = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P7021_SQL                    := :P7021_DVPOST_FUNC_BODY;',
'                :P7021_FUNCTION_BODY_LANGUAGE := :P7021_DVPOST_FUNC_BODY_LANG;',
'            end if;',
'            :P7021_REMOTE_SERVER_ID           := null;',
'            :P7021_WEB_SRC_MODULE_ID          := null;',
'            :P7021_INCLUDE_ROWID_COLUMN       := ''N'';',
'            :P7021_SOURCE_POST_PROCESSING     := nullif ( :P7021_DVPOST, ''NONE'' );',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_json_source then',
'',
'            :P7021_WEB_SRC_ARRAY_COL_ID := :P7021_JSONSRC_ARRAYCOL_ID;',
'            :P7021_DOCUMENT_SOURCE_ID   := :P7021_JSON_SOURCE_ID;',
'',
'            if :P7021_JSPOST = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P7021_QUERY_WHERE            := :P7021_JSPOST_WHERE;',
'                :P7021_QUERY_ORDER_BY         := :P7021_JSPOST_ORDERBY;',
'                :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            elsif :P7021_JSPOST = ''SQL'' then',
'                :P7021_SQL                    := :P7021_JSPOST_QUERY;',
'                :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            elsif :P7021_JSPOST = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P7021_SQL                    := :P7021_JSPOST_FUNC_BODY;',
'                :P7021_FUNCTION_BODY_LANGUAGE := :P7021_JSPOST_FUNC_BODY_LANG;',
'            end if;',
'            :P7021_REMOTE_SERVER_ID           := null;',
'            :P7021_WEB_SRC_MODULE_ID          := null;',
'            :P7021_INCLUDE_ROWID_COLUMN       := ''N'';',
'            :P7021_SOURCE_POST_PROCESSING     := nullif ( :P7021_DVPOST, ''NONE'' );',
'',
'        end if;',
'',
'    elsif :P7021_SOURCE_TYPE = ''FUNC_BODY_RETURNING_BOOLEAN'' then',
'        :P7021_LOCATION          := :P7021_FUNC_BODY_BOOL_LOCATION;',
'        :P7021_TABLE_RESULT_TYPE := ''FUNC_BODY_RETURNING_BOOLEAN'';',
'',
'        if :P7021_FUNC_BODY_BOOL_LOCATION = ''LOCAL'' then',
'            :P7021_SQL                    := :P7021_LOCAL_FUNC_BODY_BOOLEAN;',
'            :P7021_FUNCTION_BODY_LANGUAGE := :P7021_LOCAL_FUNCBODYBOOL_LANG;',
'            :P7021_REMOTE_SERVER_ID       := null;',
'        else',
'            :P7021_SQL                    := :P7021_REMOTE_PLSQL_BOOLEAN;',
'            :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            :P7021_REMOTE_SERVER_ID       := :P7021_PLSQL_REMOTE_SERVER_ID;',
'        end if;',
'',
'        clear_table;',
'        clear_json;',
'',
'    elsif :P7021_SOURCE_TYPE = ''ALWAYS'' then',
'        :P7021_TABLE_RESULT_TYPE      := ''ALWAYS'';',
'        :P7021_SQL                    := null;',
'        :P7021_REMOTE_SERVER_ID       := null;',
'        :P7021_FUNCTION_BODY_LANGUAGE := null;',
