,p_field_template=>wwv_flow_imp.id(561549638722251517.4008)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    \C2E4\D589\D560 PL/SQL \CF54\B4DC\B97C \C81C\ACF5\D569\B2C8\B2E4. \C790\B3D9\D654 \C9C8\C758\C758 \C5F4 \AC12\C740 \C5F4 \C774\B984\C5D0 \B530\B77C <strong>:EMPNO</strong>, <strong>:ENAME</strong> \B4F1\ACFC \AC19\C774 \BC14\C778\B4DC \BCC0\C218\B85C \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \B610\D55C APEX\B294 \B2E4\C74C \C77C\BC18 \BC14\C778\B4DC \BCC0\C218\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
'</p>',
'<ul>',
unistr('    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: \AE30\BCF8 \D0A4 \C5F4\C774 \C815\C758\B41C \ACBD\C6B0 \C774 \BC14\C778\B4DC \BCC0\C218\C5D0\B294 \AE30\BCF8 \D0A4 \AC12\C774 \D3EC\D568\B429\B2C8\B2E4.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: \C9C8\C758\B97C \AE30\BC18\C73C\B85C \D558\B294 \C790\B3D9\D654\C758 \ACBD\C6B0, \C774 \BC14\C778\B4DC \BCC0\C218\C5D0 \D604\C7AC \D589 \BC88\D638\AC00 \D3EC\D568\B429\B2C8\B2E4.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: \C9C8\C758\B97C \AE30\BC18\C73C\B85C \D558\B294 \C790\B3D9\D654\C758 \ACBD\C6B0 \C774 \BC14\C778\B4DC \BCC0\C218\C5D0 \C791\C5C5\C5D0\C11C \C624\B958\AC00 \BC1C\C0DD\D55C \D589 \BC88\D638\AC00 \D3EC\D568\B429\B2C8\B2E4.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: <em>\C774\C804</em> \C790\B3D9\D654 \C2E4\D589\C758 \C2DC\AC04\AE30\B85D\C774 <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong> \D615\C2DD\C73C\B85C \D3EC\D568\B429\B2C8\B2E4.</li>        '),
'</ul>',
'<p style="padding-top: 10px">',
unistr('    REST \C0AC\C6A9 SQL \C11C\BE44\C2A4\C5D0\C11C\B294 <strong>APEX_AUTOMATION</strong> \D328\D0A4\C9C0\B97C \C0AC\C6A9\D558\C9C0 \BABB\D560 \C218 \C788\C2B5\B2C8\B2E4. \C2E4\D589 \B85C\ADF8(<strong>LOG_WARN</strong>, <strong>LOG_INFO</strong>, <strong>LOG_ERROR</strong>)\C5D0 \BA54\C2DC\C9C0\B97C \CD94\AC00\D558\B824\BA74 <em>\B85C\CEEC \B370\C774\D130\BCA0\C774\C2A4</em>\C5D0\C11C \C2E4\D589\B418\B294 <em>\B2E4\B978</em> \C791\C5C5\C744 \C0DD\C131\D569\B2C8\B2E4.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
