'<p>',
unistr('    \C2E4\D589\D560 PL/SQL \CF54\B4DC\B97C \C81C\ACF5\D569\B2C8\B2E4. \C790\B3D9\D654 \C9C8\C758\C758 \C5F4 \AC12\C740 \C5F4 \C774\B984\C5D0 \B530\B77C <strong>:EMPNO</strong>, <strong>:ENAME</strong> \B4F1\ACFC \AC19\C774 \BC14\C778\B4DC \BCC0\C218\B85C \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \B610\D55C &PRODUCT_NAME.\C740(\B294) \B2E4\C74C \C77C\BC18 \BC14\C778\B4DC \BCC0\C218\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
