'               p_checksum_type => ''SESSION'')     ',
'       else',
'           wwv_flow_utilities.fast_replace_manyf (',
'               p_srcstr => nvl(d.edit_url, ''f?p=4000:4001:%session%::::F4000_P1_FLOW,FB_FLOW_ID:%pk_value%,%pk_value%''),',
'               oldsub   => wwv_flow_t_varchar2(''%application_id%'', ''%page_id%'', ''%pk_value%'',    ''%parent_pk_value%'', ''%session%''),',
'               newsub   => wwv_flow_t_varchar2(:FB_FLOW_ID,        d.page_id,   d.component_id,  null,                 :APP_SESSION))              ',
'       end as link,',
'       nvl2(d.page_id, wwv_flow_lang.system_message(''DEP.PAGE'', d.page_id)||'' &rarr; '', null) || ',
'       d.component_type_name || '' &rarr; ''||',
