,p_cSize=>100
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4008)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p><strong>[schemaName.[packageName.]]procedureName</strong> \D615\C2DD\C73C\B85C PL/SQL \D504\B85C\C2DC\C800\C758 \C774\B984\C744 \C9C0\C815\D569\B2C8\B2E4. '),
unistr('\D574\B2F9 \D504\B85C\C2DC\C800\B294 \C774 \D0DC\C2A4\D06C \C815\C758\C5D0 \B300\D55C \CD94\AC00 \B300\CCB4 \CC38\AC00\C790\B97C \BC18\D658\D574\C57C \D569\B2C8\B2E4.'),
unistr('\D734\AC00 \ADDC\CE59 \D504\B85C\C2DC\C800\B294 \B2E4\C74C \C778\D130\D398\C774\C2A4\B97C \AD6C\D604\D574\C57C \D569\B2C8\B2E4.</p>'),
'<pre>',
'    procedure my_vacation_rule (',
'        p_param    in apex_approval.t_vacation_rule_input,',
'        p_result  out apex_approval.t_vacation_rule_output );',
'</pre>',
unistr('<p>\D504\B85C\C2DC\C800 \C785\B825\C758 \C720\D615\C740 <strong>apex_approval.t_vacation_rule_input</strong>\C774\BA70, \ACB0\ACFC \CD9C\B825\C758 \C720\D615\C740 <strong>apex_approval.t_vacation_rule_output</strong>\C785\B2C8\B2E4. </p>'),
'<p>',
unistr('\C774 \C608\C5D0\C11C\B294 JANE\C758 \CD9C\C0B0 \D734\AC00 \C911 SCOTT\AC00 \B300\CCB4 \CC38\AC00\C790\B85C \CD94\AC00\B418\B294 \D734\AC00 \ADDC\CE59 \D504\B85C\C2DC\C800 '),
unistr('\AD6C\D604\C744 \BCF4\C5EC\C90D\B2C8\B2E4.</p>'),
'<pre>',
'',
'    procedure alternate_job_approvers(',
'                p_param    in apex_approval.t_vacation_rule_input,',
'                p_result  out apex_approval.t_vacation_rule_result)',
'    is ',
'        l_result            apex_approval.t_vacation_rule_result;',
'        l_changes           apex_approval.t_task_participant_changes;',
'        l_participants      apex_approval.t_task_participants;',
'        l_new_participant   apex_approval.t_task_participant;',
'        l_old_participant   apex_approval.t_task_participant;',
'        l_has_changed       boolean                             := false;',
'        l_index             pls_integer                         := 1;',
'    begin',
'        l_participants := p_param.original_participants;',
'        for i in 1..l_participants.count loop',
'            if l_participants(i).value = ''JANE'' then',
'                l_old_participant               :=  l_participants(i);',
'                l_new_participant.value         := ''SCOTT'';',
'                l_new_participant.type          := ''POTENTIAL_OWNER'';',
'                l_new_participant.identity      := ''USER'';',
'                l_has_changed                   := true;',
'            end if;',
'        end loop;',
'        if l_has_changed then',
'            l_participants(l_participants.count + 1) := l_new_participant;',
'        ',
'            l_changes(l_index).old_participant   := l_old_participant;',
'            l_changes(l_index).new_participant   := l_new_participant;',
'            l_changes(l_index).change_reason     := ''Jane is out on maternity leave'';',
'        end if;',
'        l_result.participant_changes            := l_changes;',
'        l_result.has_participant_changes        := l_has_changed;',
'        p_result                                := l_result;',
'    end;',
'</pre>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
