wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4400560466135801.4008)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch Due On Value'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare     ',
'    l_due_on varchar2(4000);',
'begin',
'    select due_on_interval into l_due_on ',
'      from wwv_flow_task_defs',
'     where id = :P9502_ID',
'       and security_group_id = :WORKSPACE_ID;',
'',
'    if l_due_on is not null then   ',
'        if :P9502_DUE_ON_TYPE    = ''INTERVAL''  then',
'            :P9502_DUE_ON_INTERVAL      := l_due_on;',
'        elsif :P9502_DUE_ON_TYPE = ''SCHEDULER_EXPRESSION'' then',
'            :P9502_DUE_ON_SCHEDULER_VAL := l_due_on;',
'        elsif :P9502_DUE_ON_TYPE = ''EXPRESSION'' then',
'            :P9502_DUE_ON_EXPRESSION    := l_due_on;',
'        elsif :P9502_DUE_ON_TYPE = ''FUNCTION_BODY'' then',
'            :P9502_DUE_ON_FUNCTION_BODY := l_due_on;',
'        elsif :P9502_DUE_ON_TYPE = ''SQL_QUERY'' then',
'            :P9502_DUE_ON_QUERY         := l_due_on;',
'        end if;',
'    end if;',
'end;    ',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>4400560466135801.4008
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1497869624762210.4008)
,p_process_sequence=>20
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch Max Renewal Count'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare     ',
'    l_max_renewal_count number;',
'begin',
'    select max_renewal_count into l_max_renewal_count ',
'      from wwv_flow_task_defs',
'     where id = :P9502_ID',
'       and security_group_id = :WORKSPACE_ID;',
'',
'    if l_max_renewal_count is null then   ',
'        :P9502_MAX_RENEWAL_COUNT := 3;',
'    end if;',
'end;    ',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1497869624762210.4008
);
