'       as workflow_url,',
'       w.static_id,',
'       w.title,',
'       w.workflow_comment,',
'       w.last_updated_by,',
'       w.last_updated_on,',
'       (select count(v.ID) ',
'          from wwv_flow_workflow_versions v ',
'         where v.workflow_id=w.id',
'           and v.security_group_id = w.security_group_id',
'           and v.state = ''ACTIVE'') active_version_count,',
'       (select count(v.id) ',
'          from wwv_flow_workflow_versions v ',
'         where v.workflow_id=w.id',
'           and v.security_group_id = w.security_group_id',
'           and v.state = ''DEVELOPMENT'') dev_version_count,',
'       (select count(v.id) ',
'          from wwv_flow_workflow_versions v ',
'         where v.workflow_id=w.id',
'           and v.security_group_id = w.security_group_id',
'           and v.state = ''INACTIVE'') inactive_version_count,',
'       (select count(p.id) ',
'          from wwv_flow_workflow_variables p',
'         where p.workflow_id=w.id ',
'           and p.security_group_id = w.security_group_id',
'           and p.direction != ''VARIABLE'') params_count',
' from wwv_flow_workflows w ',
'where w.flow_id = :FB_FLOW_ID ',
'  and w.security_group_id = :WORKSPACE_ID'))
