,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4008)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Pages utilizing Workflow',
'select  ',
'    w.id                    workflow_id,',
'    w.name                  workflow_name,',
'    wwv_flow_utilities.prepare_url(''f?p=4000:9600:''||:flow_session||''::NO:1:FB_FLOW_ID,F4000_P1_FLOW:''||:FB_FLOW_ID||'',''||:FB_FLOW_ID||''#8800:''||w.id )',
'                            workflow_url,',
'    wwv_flow_utilities.prepare_url(''f?p=4000:4500:''||:flow_session||''::::FB_FLOW_PAGE_ID:''||p.id) ',
'                            the_url,',
'    p.id                    page_id, ',
'    p.name                  reference_name,',
'    pr.process_name         process_name',
' from wwv_flow_steps           p,',
'      wwv_flow_step_processing pr,',
'      wwv_flow_workflows       w',
'where pr.flow_id           = :FB_FLOW_ID',
'  and pr.security_group_id = :FLOW_SECURITY_GROUP_ID',
'  and pr.process_type     = ''NATIVE_WORKFLOW''',
'  and pr.attribute_01     = ''START''',
'   --',
'  and p.flow_id           = pr.flow_id',
'  and p.security_group_id = pr.security_group_id',
'  and p.id                = pr.flow_step_id',
'   --',
'   -- for translated applications, ATTRIBUTE_02 contains a VARCHAR2 with decimal character,',
'   -- and that character might be different from the current session NLS settings. So we need',
'   -- to normalize this.',
'  and w.id                = to_number( replace( replace( pr.attribute_02, '','', ''.'' ), ''.'', wwv_flow.get_nls_decimal_separator ) )',
'  and w.security_group_id = p.security_group_id',
'  and w.flow_id           = p.flow_id',
'--',
'union all',
'-- Workflows utilizing  workflow',
'select  ',
'    w_child.id               workflow_id,',
'    w_child.name             workflow_name,',
'    wwv_flow_utilities.prepare_url(''f?p=4000:9600:''||:flow_session||''::NO:1:FB_FLOW_ID,F4000_P1_FLOW:''||:FB_FLOW_ID||'',''||:FB_FLOW_ID||''#8800:''||w_child.id )',
'                             workflow_url,',
'    wwv_flow_utilities.prepare_url(''f?p=4000:9600:''||:flow_session||''::NO:1:FB_FLOW_ID,F4000_P1_FLOW:''||:FB_FLOW_ID||'',''||:FB_FLOW_ID||''#8830:''||wact.id )                       ',
'                             the_url,',
'     null                    page_id, ',
'     w_parent.name           reference_name, ',
'     wact.name               process_name',
' from wwv_flow_workflow_activities      wact,',
'      wwv_flow_workflows                w_child,',
'      wwv_flow_workflows                w_parent,',
'      wwv_flow_workflow_versions        wver',
'where wact.flow_id               = :FB_FLOW_ID',
'  and wact.security_group_id     = :WORKSPACE_ID',
'  and wact.activity_type         = ''NATIVE_INVOKE_WF''',
'  --',
'  and w_child.id                 = wact.workflow_id',
'  and w_child.flow_id            = wact.flow_id',
'  and w_child.security_group_id  = wact.security_group_id',
'  -- ',
'  and wver.id                    = wact.workflow_version_id',
'  and wver.flow_id               = wact.flow_id',
'  and wver.security_group_id     = wact.security_group_id',
'  --',
'  and w_parent.id                = wver.workflow_id',
'  and w_parent.flow_id           = wver.flow_id',
'  and w_parent.security_group_id = wver.security_group_id',
'  --',
'  order by workflow_id'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
