'        objectType;',
'',
'    checkItemAndAddError( "P9811_OCI_COMPARTMENT_ID", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.COMPARTMENT_VALIDATION" ), errorsArray );',
'    checkItemAndAddError( "P9811_OCI_MODEL_ID", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_MODEL_VALIDATION" ), errorsArray );',
'    checkItemAndAddError( "P9811_BASE_URL", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_BASE_URL_VALIDATION" ), errorsArray );',
'    ',
'    if( apex.item( "P9811_OCI_CREDENTIAL_ID" ).isEmpty() ){',
'        checkItemAndAddError( "P9811_OCI_USER_ID", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.USERID_VALIDATION" ), errorsArray );',
'        checkItemAndAddError( "P9811_OCI_PRIVATE_KEY", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.PRIVATEKEY_VALIDATION" ), errorsArray );',
'        checkItemAndAddError( "P9811_OCI_TENANCY_ID", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.TENANCY_VALIDATION" ), errorsArray );',
'        checkItemAndAddError( "P9811_OCI_FINGERPRINT", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.FINGERPRINT_VALIDATION" ), errorsArray );',
'    }',
